options.onCreated:
/**
 * pt_header · onCreated — เตรียม helper ให้ content ของการ์ดคนไข้ (D4.4)
 *
 * 🔴 ทุกตัวเป็น "function" ไม่ใช่ค่า snapshot — onCreated รันครั้งเดียว ถ้า copy ค่าจาก formModel
 *    ไว้ตรง ๆ แล้วค่าเปลี่ยนทีหลัง (แม่ยิง setValue เพิ่ม) การ์ดจะไม่ตาม (LLM-VueUI ข้อ 11)
 *    เก็บเป็น arrow function ที่อ่าน field.params สดทุกครั้ง → Vue track dep ให้เอง
 *
 * 🔴 อ่านผ่าน field.params (= getFormRef().formParams) ไม่ใช่ field.formModel
 *    เดิมอ่าน formModel แล้วการ์ดขึ้น "ไม่มีข้อมูลผู้ป่วย" ตลอด — สาเหตุ (verify กับ runtime 2026-08-04):
 *    SdFormRender.buildDataModel() คัดค่าจาก formData เข้า formDataModel เฉพาะ field ที่ `formItemFlag: true`
 *    จอนี้เป็น form_ui ที่มีแต่ vue-ui (formItemFlag: false) ⇒ ไม่มี field ให้ค่าลง
 *    ⇒ field.formModel เหลือแต่ system key (_id/xsitex/xunitx/…) ไม่ว่าปุ่มจะส่ง initData มาครบแค่ไหน
 *    ⇒ ปุ่มฝั่ง EMR จึงส่ง patient context ทาง `params` แทน (emr-drug-order-button.js)
 *
 * 🔴 อ่านผ่าน field.params ไม่ใช่ identifier ตรง ๆ ในเทมเพลต — ให้จุดอ่านอยู่ที่เดียว
 *    ตรงกับที่ scope proxy ให้ params ชนะ state/data อยู่แล้ว (SDCustomContent.buildScopeProxy)
 *
 * 🔴 field lifecycle event ไม่มีตัวแปร event ให้ (userInfo/data/value ใช้ไม่ได้ตรง ๆ)
 *    ต้องใช้ this.globalUserState / this.formParams แทน
 */

const s = this.vueState;
const field = this;

// patient context ทั้งชุดมาทาง params (ดูหัวไฟล์) — computed reactive ของ CoreFieldMixin
// อ่านสดทุกครั้ง ไม่ snapshot: ค่าเปลี่ยนแล้วการ์ดตามเอง
s.manualContext = null;
s.vnQuery = '';
s.vnRows = [];
s.vnLoading = false;
s.vnError = '';
s.selectedVisitId = '';
const formRef = () => field.getFormRef && field.getFormRef();
const m = () => s.manualContext || ((formRef() || {}).$labCpoeContext) || field.params || {};
s.manualMode = () => !!((field.params || {}).manual_visit);
s.setVnQuery = value => { s.vnQuery = String(value || '').trim(); s.vnError = ''; };
s.visitPatient = visit => (visit && visit.pid) || {};
s.visitName = visit => {
  const p = s.visitPatient(visit);
  return [((p.prename || {}).label || ''), p.p_fname || '', p.p_lname || ''].join(' ').replace(/\s+/g, ' ').trim();
};
s.visitContext = visit => {
  const p = s.visitPatient(visit);
  const gender = ({'1':'ชาย','2':'หญิง'})[String(p.p_gender || '')] || '';
  const photo = Array.isArray(p.p_pic) ? p.p_pic : null;
  return {
    person_id: String(visit.xtbxlv1_xfx_id || ((visit.pid || {}).value) || ''),
    hn: p.hn || '',
    full_name: s.visitName(visit),
    sex: gender,
    age: p.age == null ? '' : p.age,
    blood_group: p.p_abogroup || '',
    p_pic: photo,
    allergy_tags: [],
    visit_id: String(visit._id || visit.value || ''),
    vn: visit.vn || '',
    visit_type: (visit.visit_type && (visit.visit_type.label || visit.visit_type.value)) || visit.visit_type || '',
    visit_datetime: visit.visit_date || visit.created_at || '',
    visit_clinic: (visit.visit_clinic && (visit.visit_clinic.label || visit.visit_clinic.value)) || '',
    visit_doctor: (visit.visit_doctor && (visit.visit_doctor.label || visit.visit_doctor.value)) || '',
    dx_summary: '',
    service_type: '',
    inscl_hos: Array.isArray(visit.inscl_hos) ? visit.inscl_hos : []
  };
};
s.selectVisit = visit => {
  const ctx = s.visitContext(visit);
  if(!ctx.visit_id) return;
  s.selectedVisitId = ctx.visit_id;
  s.manualContext = ctx;
  const form = formRef();
  if(form) form.$labCpoeContext = ctx;
  const item = field.getFieldRef && field.getFieldRef('item_screen');
  if(item && item.vueState && typeof item.vueState.setPatientContext === 'function') item.vueState.setPatientContext(ctx);
};
s.findVisits = () => {
  const vn = String(s.vnQuery || '').trim();
  if(!vn){ s.vnError = 'กรอก VN ก่อนค้นหา'; s.vnRows = []; return; }
  const form = formRef();
  if(!form || !form.userState || typeof form.userState.crudGetAll !== 'function'){
    s.vnError = 'ไม่พบตัวเชื่อมข้อมูล Visit'; return;
  }
  s.vnLoading = true;
  s.vnError = '';
  form.userState.crudGetAll({
    sdProvider:{
      providerId:'6a40fdec4b6dfdf45acbfbce',
      providerType:'FORM',
      params:{vn:vn},
      options:{where:'vn = :vn',orderBy:[{column:'visit_date',sort:'DESC'}],limit:10,page:1}
    },
    totalEnable:false
  },res=>{
    s.vnLoading=false;
    s.vnRows=(res&&res.data)||[];
    if(!s.vnRows.length)s.vnError='ไม่พบ VN '+vn;
    if(s.vnRows.length===1)s.selectVisit(s.vnRows[0]);
  },()=>{s.vnLoading=false;s.vnRows=[];s.vnError='ค้นหา VN ไม่สำเร็จ';});
};

// ค่าที่ต้องแสดงเป็นข้อความ — คืน '' เมื่อไม่มี เพื่อให้ v-if ในเทมเพลตตัดสินได้ตรง ๆ
s.ptText = (key) => {
	const v = m()[key];
	if (v === null || v === undefined || v === '') return '';
	// เผื่อแม่ส่งมาเป็น { value, label } (select-form) — เอา label ให้คนอ่าน
	if (typeof v === 'object' && !Array.isArray(v)) return String(v.label || v.value || '');
	return String(v);
};

s.ptHas = () => !!(s.ptText('full_name') || s.ptText('hn') || s.ptText('visit_id'));

s.ptName = () => s.ptText('full_name') || '(ไม่ทราบชื่อ)';
s.ptInitial = () => {
	const n = s.ptName().trim();
	return n && n !== '(ไม่ทราบชื่อ)' ? n.charAt(0) : '?';
};

// รูปคนไข้ — รับได้ทั้ง url ตรง ๆ และโครง p_pic ของฟอร์ม Person ([{ url }])
s.ptPic = () => {
	const v = m().photo_url || m().p_pic;
	if (!v) return '';
	if (typeof v === 'string') return v;
	if (Array.isArray(v) && v[0] && v[0].url) return v[0].url;
	return '';
};

// "อายุ 25 ปี · หญิง" — รวมเป็นชิปเดียวตาม mockup (สองชิปแยกกินที่โดยไม่ได้ข้อมูลเพิ่ม)
s.ageSexText = () => {
	const age = s.ptText('age');
	const sex = s.ptText('sex');
	return [age ? 'อายุ ' + age : '', sex].filter(Boolean).join(' · ');
};

// ชิปสิทธิ์ ✓OFC ✓UCS — บอกว่าวิสิทนี้ตรวจสอบสิทธิ์อะไรมาแล้วบ้าง (ตัวที่ "ใช้" เลือกที่แถบสิทธิ์ของใบ)
s.insChips = () => {
	const arr = m().inscl_hos;
	if (!Array.isArray(arr)) return [];
	const seen = {};
	const out = [];
	arr.forEach((row) => {
		const code = String(((row || {}).inscl_item_main || {}).value || '');
		if (!code || seen[code]) return;
		seen[code] = true;
		out.push(code);
	});
	return out;
};

// มีข้อมูลร่างกายให้แสดงไหม (น้ำหนัก · ส่วนสูง · BMI · BSA)
// 🔴 ห้ามคิด BMI/BSA เองในจอนี้ — แม่คิดมาแล้วส่งค่ามา (D4.4) คิดซ้ำแล้วสูตรต่างกัน สองจอจะโชว์คนละเลข
s.hasBody = () => !!(s.ptText('weight') || s.ptText('height') || s.ptText('bmi') || s.ptText('bsa'));

/* ── Vital signs ────────────────────────────────────────────────────────────
   🔴 ไม่ฝังเกณฑ์ค่าปกติไว้ในจอสั่งยา (D4.4 · D12 ข้อ 4 ยังไม่เคาะว่าเกณฑ์มาจากไหน)
      รับได้ 2 รูป:
        bp: '120/80'                      → แสดงเฉย ๆ ไม่ทำสี
        bp: { value: '120/80', level: 'warn' } → ทำสีตามระดับที่แม่ส่งมา
      แม่ (หน้า EMR) มี vsRules อยู่แล้วใน opd_card จึงเป็นคนตัดสินระดับ ที่เดียวทั้งระบบ */
const VITALS = [
	{ key: 'bp', label: 'BP', unit: 'mmHg' },
	{ key: 'pr', label: 'PR', unit: '/นาที' },
	{ key: 'temp', label: 'Temp', unit: '°C' },
	{ key: 'rr', label: 'RR', unit: '/นาที' },
];
// ชื่อ class ของ pcard (CSS global ของแอป) — ชุดเดียวกับที่ opd_card ใช้ในหน้า EMR
// 🔴 แม่ (opd_card.vsClass) ส่ง level มาเป็น 'warn'/'bad' — ต้อง map เป็น is-warning/is-danger ที่นี่
//    เขียนชื่อ class ผิด = ค่าที่ผิดปกติจะโชว์เป็นสีปกติ โดยไม่มี error ให้เห็น
const LEVEL_CLASS = { warn: 'is-warning', warning: 'is-warning', bad: 'is-danger', danger: 'is-danger' };

s.vitals = () => {
	const data = m();
	const out = [];
	VITALS.forEach((v) => {
		const raw = data[v.key];
		if (raw === null || raw === undefined || raw === '') return;
		const isObj = typeof raw === 'object' && !Array.isArray(raw);
		const value = isObj ? raw.value : raw;
		if (value === null || value === undefined || value === '') return;
		out.push({
			key: v.key,
			label: v.label,
			unit: v.unit,
			value: String(value),
			cls: (isObj && LEVEL_CLASS[String(raw.level || '').toLowerCase()]) || '',
		});
	});
	return out;
};

// แถบแพ้ยา — allergy_tags เป็น string ที่ api-checkin สร้างไว้ (เช่น "💊 พารา 🔴")
// 🔴 เป็นแค่ป้ายบอก เทียบกับยาไม่ได้ (D8.3 ชั้น 1) → ข้อความท้ายแถบต้องไม่อ่านว่า "ตรวจแล้ว"
s.allergyTags = () => {
	const v = m().allergy_tags;
	if (!v) return [];
	if (Array.isArray(v)) return v.map((x) => String(x)).filter(Boolean);
	return String(v).split(',').map((x) => x.trim()).filter(Boolean);
};

/**
 * item_screen · onCreated — จอสั่งตรวจ/บริการ (ฟอร์ม CPOE Order App 6a927860422c1ca959829d26)
 *
 * แปลงจาก design/mockup/cpoe-item-order.tpl.html (C12) — กติกาทุกข้อยกมาจาก mockup ที่พี่ตรวจแล้ว
 * แก้พฤติกรรมที่นี่แล้วต้องแก้ mockup ด้วย ไม่งั้นต้นแบบกับของจริงจะเล่าคนละเรื่อง
 *
 * รอบนี้ (รอบ A) ครบ: segment · ความเร่งด่วน · สิทธิ์ · แถบ section · ติ๊กชีท · แถบกรอง X-ray · ค้นหา · ตะกร้า
 * รอบถัดไป (รอบ B): โหมด pick (หัตถการ/บริการอื่นๆ) · สิ่งส่งตรวจ · ยาที่เคยรับ · ประวัติการสั่ง · บันทึก/ส่งใบ
 *
 * 🔴 อ่าน patient context ผ่าน `field.params` ไม่ใช่ `field.formModel` — form_ui ที่มีแต่ vue-ui
 *    ตัด initData ทิ้งใน buildDataModel ⇒ ฟอร์มแม่ต้องส่ง context ทาง `params`
 * 🔴 เทมเพลตอ่านจาก `s.view` ที่ recompute() ทำไว้ให้ ไม่ใช่คำนวณสดในเทมเพลต —
 *    ติ๊กชีทมี 150-230 แถวต่อ section ถ้าเทมเพลตเรียกฟังก์ชันคำนวณ จะคำนวณซ้ำทุก binding ที่แตะมัน
 * 🔴 ห้ามให้เทมเพลตเขียนค่ากลับเข้า vueState (scope proxy ไม่มี set) ⇒ ทุกการเปลี่ยนค่าผ่าน method ที่นี่
 * 🔴 ทุก key ที่เทมเพลตอ้างต้องมีค่าตั้งแต่ตรงนี้ — ขาดตัวเดียว = error box ทั้ง widget
 */

const s = this.vueState;
const field = this;

const CATALOG_PROC = '6a9279a945ee4b7a59a1f049'; // cpoe-item-catalog
const HISTORY_PROC = '6a929f6d1eb7b2ece2b4f035'; // cpoe-item-history (ใบเก่าข้ามวิสิท)
const GET_PROC = '6a92a813c81f441a61358cf4'; // cpoe-item-get (อ่านใบเดิมกลับเข้าตะกร้า)
const SAVE_PROC = '6a71edd247075049ef0245af'; // cpoe-order-save (สร้าง/แก้ใบร่าง — ตัวเดียวกับจอสั่งยา)
const SEND_PROC = '6a757d1bf7bf7668d7673c63'; // cpoe-order-send (draft → sent)
const FORM_ITEM_MASTER = '6a594763d448dfc9d33e2c27'; // CPOE Item → zdata_master_item_order

/* ══ config — ยกมาจาก mockup ═══════════════════════════════════════════════
   mode 'sheet' = ติ๊กชีท · 'pick' = เลือกทีละรายการ · prefix = ตัวออกเลขที่ใบ (design §D4.1)
   ยา (med) ไม่อยู่ในจอนี้ — สั่งยาใช้จอของตัวเอง (พี่สั่ง 2026-08-28) */
const TYPES = [
	{ code: 'lab', label: 'Lab', prefix: 'L', mode: 'sheet', spec: true },
	{ code: 'xray', label: 'X-ray', prefix: 'X', mode: 'sheet' },
	{ code: 'nurs', label: 'หัตถการ', prefix: 'N', mode: 'pick' },
	{ code: 'order', label: 'บริการอื่นๆ', prefix: 'O', mode: 'pick' },
];
// ประวัติการสั่ง ไม่ใช่ชนิดรายการ — คั่นไว้ท้ายแถบ ไม่ให้ปนกับ 4 ตัวบน
const HISTORY = { code: 'history', label: 'ประวัติการสั่ง', mode: 'history' };

// ค่าเดียวกับฟอร์ม CPOE Order (6a6f5cd1265885c2377cc218)
// cls: w = ระดับเตือน (ส้ม) · d = ด่วนจริง (แดง) · quick = โชว์เป็นปุ่มถาวร ที่เหลือซ่อนใน "อื่นๆ"
// 🔴 พี่ตีกลับแบบ 5 ปุ่มเรียงแล้วว่าแถบรก — อย่าเปลี่ยนกลับ
const PRIORITY = [
	{ v: '1', label: 'ปกติ', cls: '', quick: true },
	{ v: '2', label: 'ด่วน', cls: 'w', quick: true },
	{ v: '3', label: 'ด่วนที่สุด', cls: 'd' },
	{ v: '4', label: 'ด่วน OR', cls: 'd' },
	{ v: '5', label: 'ด่วน อุบัติเหตุ', cls: 'd' },
];

/* specimen ที่ "ไม่รู้ว่าเก็บอะไร" — ต้องให้คนสั่งระบุเอง ไม่งั้นห้องแลปได้ใบไปแล้วเก็บไม่ถูก
   ตรวจจากของจริงใน zdata_master_item_order: 99=Others · XX=Specimen · M50=Other · ไม่ผูก specimen เลย
   🔴 `X099` ไม่มีในฐานจริง (เคยเข้าใจว่ามี) — เก็บไว้กันเผื่อวันหนึ่งมีคนเพิ่ม ไม่ใช่ของที่ใช้อยู่ */
const SPEC_VAGUE = ['99', 'XX', 'M50', 'X099'];
/* 🔴 ชุด group ถามสิ่งส่งตรวจครั้งเดียว — ถามที่บรรทัดแรกของชุด ที่เหลือรับค่าตามไป
   ไม่กันไว้ = ติ๊ก Electrolyte ทีเดียวแล้วจอบังคับให้กรอกสิ่งส่งตรวจ 4 รอบ ทั้งที่เจาะหลอดเดียว */
const needSpec = (l) => l.st === 'lab' && isSetLead(l) && (!l.sp || SPEC_VAGUE.indexOf(l.sp) >= 0);
const STORAGE = { IM: 'ส่งทันที', RF: 'ตู้เย็น', RT: 'อุณหภูมิห้อง' };
// ตัวย่อสำหรับแถบ 1 บรรทัด — ชื่อเต็มไปอยู่ใน tooltip
const STORAGE_SHORT = { IM: 'ทันที', RF: 'ตู้เย็น', RT: 'ห้อง' };
const PRIOR_MED = [{ v: '1', label: 'ยังไม่ได้รับ' }, { v: '2', label: 'ได้รับแล้ว' }];
const PICK_LIMIT = 200; // โหมด pick โชว์ได้มากสุดกี่แถว — 4,350 รายการเลื่อนดูจบไม่ไหว ต้องพิมพ์ค้น


const BIG_GROUP = 22; // กลุ่มที่ยาวกว่านี้ต้องปล่อยให้ตัดข้ามคอลัมน์ได้ ไม่งั้นคอลัมน์เดียวยาวเกินจอ

/* ══ state ════════════════════════════════════════════════════════════════ */
s.cat = {}; // แคตตาล็อกทั้งชุด — โหลดครั้งเดียว ห้ามยิงซ้ำตอนสลับแท็บ/section
s.catCounts = {};
s.catLoading = false;
s.catErr = '';
s.catLoaded = false;

s.TYPES = TYPES;
s.HISTORY = HISTORY;
s.PRIORITY_QUICK = PRIORITY.filter((p) => p.quick);
s.PRIORITY_MORE = PRIORITY.filter((p) => !p.quick);

s.st = 'lab'; // ชนิดที่เปิดอยู่
s.sec = {}; // section ที่เปิดอยู่ ต่อชนิด
s.q = {}; // คำค้น ต่อชนิด
s.grp = {}; // แถบกรองชั้น 1 (xray) — '' ทั้งหมด · '<group code>' · 'rest' = ยังไม่ได้จัดกลุ่ม
s.bp = {}; // แถบกรองชั้น 2 — '' ทั้งกลุ่ม · '<body part code>'
s.cart = [];
s.prio = '1';
s.prioOpen = false;
s.insIx = 0; // index ใน insList() · -1 = ไม่มีสิทธิ์/ชำระเอง
s.PRIOR_MED = PRIOR_MED;
s.priorMed = ''; // '' = ยังไม่ตอบ (ฟอร์มจริงไม่บังคับตอบ)
s.priorSpec = ''; // ใช้เมื่อตอบ "ได้รับแล้ว"

// กล่องกรอกสิ่งส่งตรวจ — ทีละรายการ (specIx = index ในตะกร้า · -1 = ปิด)
s.specIx = -1;
s.specForm = { source: '', storage: 'IM', at: '', by: '' };

// ผลลัพธ์ที่เทมเพลตอ่าน — recompute() เป็นคนเติมให้ทั้งก้อน
s.view = { rail: [], groups: [], head: { title: '', sub: '' }, fbar: null, empty: false, pick: null };

/* ══ patient context ══════════════════════════════════════════════════════ */
s.manualContext = null;
s.pt = () => s.manualContext || (((field.getFormRef && field.getFormRef()) || {}).$labCpoeContext) || field.params || {};
s.ptOk = () => !!(s.pt() && s.pt().visit_id);
s.itemMode = () => ((s.pt() || {}).order_id ? 'edit' : 'new');
s.setPatientContext = ctx => {
  s.manualContext = ctx || null;
  s.cart = [];
  s.specIx = -1;
  s.catErr = '';
  if(typeof s.boot === 'function') s.boot();
};
/* ══ แพทย์ผู้สั่ง ═════════════════════════════════════════════════════════
   🔴 คนกดบันทึกไม่ใช่คนสั่งเสมอไป — พยาบาล/ผู้ช่วยคีย์แทนได้ ⇒ ต้องเลือกได้
   ใช้ provider ตัวเดียวกับจอสั่งยา (`cpoe-doctor-list` กรอง roles LIKE 'DOCTOR' — พี่เคาะ 08-09)
   ⇒ สองจอเห็นรายชื่อชุดเดียวกันเสมอ · ไม่มี entity "รายชื่อหมอ" แยกให้ดูแลอีกชุด
   ⚠️ จอส่งแค่ id ไป — ชื่อที่ลงใบ process resolve จาก core_user เอง ไม่เชื่อ label จากจอ */
const DOCTOR_PROVIDER = '6a787a8a2294ae4131e6c268'; // cpoe-doctor-list (module_sql)

s.docList = [];
s.docLoading = false;
s.docId = '';

s.docLabel = (row) => {
	if (!row) return '';
	const name = [row.fname, row.lname].filter(Boolean).join(' ').trim() || row.username || '(ไม่มีชื่อ)';
	return row.license_no ? name + ' · ว.' + row.license_no : name;
};
s.setDoc = (v) => {
	s.docId = String(v || '');
};
s.loadDoctors = () => {
	s.docLoading = true;
	field.getFormRef().userState.crudGetAll(
		{ sdProvider: { providerId: DOCTOR_PROVIDER, providerType: 'SQL', params: {} }, totalEnable: false },
		(res) => {
			const rows = (res && res.data) || [];
			// เรียงที่จอ ไม่ใช่ที่ provider — ชื่อไทย/อังกฤษปนกัน localeCompare จัดได้ตรงกว่า sort ของ mongo
			s.docList = rows.slice().sort((a, b) => String(a.fname || '').localeCompare(String(b.fname || ''), 'th'));
			s.docLoading = false;
			// ค่าเริ่มต้น = ตัวเอง ถ้าคนที่ล็อกอินอยู่เป็นหมอ (เคสปกติสุด: หมอสั่งตรวจเอง)
			if (!s.docId) {
				const u = (field.globalUserState && field.globalUserState.user) || {};
				const me = String(u._id || u.id || '');
				const hit = s.docList.find((r) => String(r.doctor_id) === me);
				if (hit) s.docId = String(hit.doctor_id);
			}
		},
		() => {
			s.docList = [];
			s.docLoading = false;
		}
	);
};

/* สิทธิ์ทั้งใบ — โครงเดียวกับที่ mockup ประกอบจาก visit.inscl_hos
   ไม่มีสิทธิ์ = คิดราคามาตรฐานทั้งใบ (ไม่ใช่บั๊ก — master ไม่มีแถวราคาตามสิทธิ์) */
s.insList = () => {
	const rows = (field.params || {}).inscl_hos;
	if (!Array.isArray(rows)) return [];
	return rows
		.filter((r) => r && r.inscl_item_main && r.inscl_item_main.value)
		.map((r) => ({
			main: r.inscl_item_main.value,
			sub: (r.inscl_item_sub && r.inscl_item_sub.value) || '',
			label: [r.inscl_item_main.label, r.inscl_item_sub && r.inscl_item_sub.label].filter(Boolean).join(' / '),
		}));
};
s.insCurrent = () => {
	const list = s.insList();
	return s.insIx >= 0 && list[s.insIx] ? list[s.insIx] : null;
};
s.setIns = (v) => {
	s.insIx = Number(v);
};
// บอกเหตุผลว่าทำไมยัง "ชำระเอง" — ไม่ใช่บั๊ก แต่เพราะ master ไม่มีแถวราคาตามสิทธิ์
s.insHint = () => {
	const ins = s.insCurrent();
	return ins
		? 'สิทธิ์ ' + ins.main + '/' + (ins.sub || '-') + ' ไม่มีแถวราคาเฉพาะใน master → ตกมาใช้ราคามาตรฐาน (ชำระเอง)'
		: 'ไม่ได้เลือกสิทธิ์ — คิดราคามาตรฐานทั้งใบ';
};

/* ══ helper ═══════════════════════════════════════════════════════════════ */
const money = (n) => '฿' + (Math.round(Number(n || 0) * 100) / 100).toLocaleString('th-TH');
s.money = money;

const typeOf = (c) => (c === HISTORY.code ? HISTORY : TYPES.find((t) => t.code === c) || TYPES[0]);
s.mode = () => typeOf(s.st).mode;
s.typeLabel = (code) => typeOf(code).label;

const keyOf = (st, item) => st + ':' + (item.id || item.c);
const inCart = (k) => s.cart.findIndex((l) => l.k === k);

/* ══ ชุดแม่-ลูก (C33 · พี่เคาะ 2026-08-30 ตาม design/lab-ui-config.drawio) ══════
   แคตตาล็อกคืน `sub` บนแม่ (= [item_code ลูก]) · `par` บนลูก (= item_code แม่)
   + `sk` บอก **กติกาของชุด** ซึ่งมี 2 แบบ ห้ามปนกัน:

   ── sk='x' exclusive (มาจาก `lab_parent` — C1 LFT · C35 GTT) ──
     แม่กับลูกเป็น **ทางเลือกแทนกัน** ติ๊กได้ทั้งคู่ ทุกบรรทัดคิดราคาจริงของตัวเอง
     ติ๊กแม่ → เคลียลูกที่อยู่ในใบ · ติ๊กลูก → เคลียแม่
     🔴 อยู่ในใบพร้อมกันไม่ได้ = เก็บเงินซ้ำ (C1 ฿320 + ลูกอีก ฿340)

   ── sk='g' group (มาจาก `sub_order` — C25-CD · C25-IC) ──
     แม่เป็นแค่ **หัวชุด ไม่มี checkbox ไม่เข้าใบ** · ลูกเข้าใบครบชุดเสมอ คิดราคาจริงรายตัว
     (ลูก ฿40×4 = ฿160 เท่าราคาแม่พอดี ⇒ ไม่ต้อง zero ใคร เงินตรงเป๊ะ)
     ติ๊กลูกตัวเดียว = ได้ครบทั้งชุด · เอาออกตัวเดียว = ออกทั้งชุด

   🔴 ไม่มีบรรทัด ฿0 ในระบบนี้แล้ว — ทุกบรรทัดในใบคือของที่เก็บเงินจริง
      (กติกาเดิมก่อน 08-30 ให้ลูก ฿0 แล้วแม่ถือราคา · เลิกใช้แล้ว ห้ามเอากลับมา)
   🔴 จอทำให้ "เห็นตรงกับที่จะถูกเก็บ" เท่านั้น — ตัวตัดสินราคาจริงคือ `cpoe-order-save`
      ที่ไปตรวจชุดกับ master เอง (จอปลอมค่าได้ ห้ามเป็นด่านสุดท้ายของเงิน) */
const isKid = (item) => !!(item && item.par);
const kidsOf = (item) => (item && Array.isArray(item.sub) ? item.sub : []);
// ลูกที่หาเจอในแคตตาล็อกจริง — ตัวที่หาไม่เจอคือถูกปิดใช้งานไปแล้ว ข้ามไปเงียบไม่ได้แปลว่าพัง
const kidItems = (st, item) => kidsOf(item).map((c) => findMaster(st, c)).filter(Boolean);
const setKind = (item) => (item && item.sk) || '';
// หัวชุดแบบ group — เป็นปุ่มเลือกทั้งชุด ไม่ใช่รายการที่สั่งได้เอง ⇒ ห้ามเข้าตะกร้า
const isGroupHead = (item) => setKind(item) === 'g' && kidsOf(item).length > 0;
// หัวชุดของแถวใดก็ได้ในชุด group (ส่งลูกมาก็คืนแม่ · ส่งแม่มาก็คืนตัวเอง)
const groupHeadOf = (st, item) => {
	if (isGroupHead(item)) return item;
	if (item && item.par && setKind(item) === 'g') {
		const h = findMaster(st, item.par);
		return isGroupHead(h) ? h : null;
	}
	return null;
};

/* สร้างบรรทัดตะกร้าจาก master — รวมไว้ที่เดียว เพราะเดิมมี object literal ซ้ำ 4 จุด
   (เพิ่ม field ทีต้องไล่แก้ครบทุกจุด ไม่งั้นบางทางเข้าตะกร้าได้บรรทัดที่ขาด field) */
const mkLine = (st, item, extra) =>
	Object.assign(
		{
			k: keyOf(st, item),
			st: st,
			id: item.id,
			c: item.c,
			n: item.n,
			p: item.p,
			cv: item.cv,
			sp: item.sp,
			spn: item.spn,
			sec: item.sec,
			one: item.one === true,
			qty: 1,
		},
		extra || {}
	);
/* บรรทัดลูกของชุด group — ราคาจริงของลูกเอง · `set` = code หัวชุด
   🔴 `set` ไม่เกี่ยวกับราคาเลย ใช้ 2 อย่างเท่านั้น: ถามสิ่งส่งตรวจครั้งเดียวต่อชุด และเข้า/ออกพร้อมกัน
      (ทั้งชุดเจาะหลอดเดียว — ถามรายบรรทัดจะบังคับหมอกรอก 4 รอบ แถบหลอดก็ขึ้น ×4) */
const mkSetLine = (st, kid, headCode) => mkLine(st, kid, { set: headCode });

/* บรรทัดแรกของชุดที่อยู่ในตะกร้า = ตัวถือสิ่งส่งตรวจแทนทั้งชุด
   🔴 ตัดสินจากลำดับในตะกร้าจริง ไม่ใช่ลำดับในแคตตาล็อก — ลูกตัวแรกของชุดอาจถูกลบแล้วเติมใหม่ */
const setLeadIx = (l) => (l && l.set ? s.cart.findIndex((x) => x.set === l.set && x.st === l.st) : -1);
const isSetLead = (l) => !l.set || s.cart[setLeadIx(l)] === l;

/* จัดบรรทัดในตะกร้าให้เข้ารูปชุด — ใช้กติกาเดียวกับ `cpoe-order-save` เป๊ะ
   เรียกหลังเติมตะกร้าจากทางที่ไม่ได้ผ่าน applyToggle (เปิดใบเดิมมาแก้ · สั่งซ้ำจากประวัติ)
   🔴 ต้องตรงกับ server — ไม่งั้นยอดที่จอโชว์กับยอดที่บันทึกจริงจะคนละตัว */
const normalizeSets = () => {
	const keyIn = () => {
		const m = {};
		s.cart.forEach((l) => {
			m[l.st + '|' + l.c] = 1;
		});
		return m;
	};

	/* 1) ชุด group — หัวชุดห้ามอยู่ในใบ (ไม่ใช่ของที่ขายได้) · ลูกต้องครบชุดเสมอ
	      ใบเก่าที่บันทึกด้วยกติกาก่อน 08-30 จะมีบรรทัดแม่ติดมา ⇒ ถอดออกแล้วเติมลูกให้ครบแทน */
	const heads = [];
	s.cart = s.cart.filter((l) => {
		const m = masterOf(l.st, l.id, l.c);
		if (!isGroupHead(m)) return true;
		heads.push({ st: l.st, m: m, qty: Number(l.qty || 1) });
		return false;
	});
	heads.forEach((h) => {
		const have = keyIn();
		kidItems(h.st, h.m).forEach((kd) => {
			if (have[h.st + '|' + kd.c]) return;
			s.cart.push(Object.assign(mkSetLine(h.st, kd, h.m.c), { qty: h.qty }));
		});
	});

	// 2) ลูกของชุด group ที่หลุดเข้ามาเดี่ยวๆ — เติมพี่น้องให้ครบ + ติดธง `set` ให้ทั้งชุด
	const fill = [];
	s.cart.forEach((l) => {
		const head = groupHeadOf(l.st, masterOf(l.st, l.id, l.c));
		if (!head) {
			if (l.set) delete l.set; // ไม่ได้อยู่ในชุด group แล้ว (master เปลี่ยนกติกา) — ธงต้องหลุดตาม
			return;
		}
		l.set = head.c;
		const have = keyIn();
		kidItems(l.st, head).forEach((kd) => {
			if (have[l.st + '|' + kd.c] || fill.some((x) => x.c === kd.c && x.st === l.st)) return;
			fill.push(Object.assign(mkSetLine(l.st, kd, head.c), { qty: Number(l.qty || 1) }));
		});
	});
	if (fill.length) s.cart = s.cart.concat(fill);

	/* 3) ชุด exclusive — แม่กับลูกอยู่ในใบพร้อมกันไม่ได้ (เก็บเงินซ้ำ)
	      🔴 **แม่ชนะ** ตรงกับ `cpoe-order-save` — หมอที่ติ๊กแม่ตั้งใจสั่งทั้งชุดในราคาชุด
	         และราคาชุดถูกกว่าซื้อแยกเสมอ ⇒ ตัดลูกออกไม่มีทางเก็บเกิน */
	const parentIn = {};
	s.cart.forEach((l) => {
		const m = masterOf(l.st, l.id, l.c);
		if (setKind(m) === 'x' && kidsOf(m).length) parentIn[l.st + '|' + l.c] = 1;
	});
	s.cart = s.cart.filter((l) => {
		const m = masterOf(l.st, l.id, l.c);
		return !(m && setKind(m) === 'x' && m.par && parentIn[l.st + '|' + m.par]);
	});

	/* 4) คืนราคาจริงจาก master ทุกบรรทัด — ใบเก่าเก็บลูกไว้ที่ ฿0 ตามกติกาที่เลิกใช้แล้ว
	      ไม่คืน = เปิดใบเก่ามาแก้แล้วยอดต่ำกว่าที่ห้องการเงินจะเก็บจริง */
	s.cart.forEach((l) => {
		const m = masterOf(l.st, l.id, l.c);
		if (!m) return;
		l.p = m.p;
		l.cv = m.cv;
		if (l.via) delete l.via; // ธงของกติกาเก่า — ตกค้างอยู่ในใบที่บันทึกก่อน 08-30
	});
};

// section ตั้งต้น = ตัวที่จัดกลุ่มไว้มากสุด (ตกมาที่รายการเยอะสุดถ้ายังไม่มีใครจัดกลุ่ม)
const defaultSection = (secs) =>
	((secs || [])
		.slice()
		.sort((a, b) => (b.g || 0) - (a.g || 0) || b.n - a.n)[0] || {}).code || '';

// ไฮไลต์คำค้นในชื่อ — ช่วยตาไล่ในชีทที่มี 200+ บรรทัด · คืนเป็น 3 ท่อนแทน HTML (เทมเพลตประกอบเอง)
const hlParts = (text, q) => {
	const t = String(text == null ? '' : text);
	if (!q) return null;
	const i = t.toLowerCase().indexOf(q.toLowerCase());
	if (i < 0) return null;
	return { a: t.slice(0, i), m: t.slice(i, i + q.length), b: t.slice(i + q.length) };
};

/* ══ ตะกร้า ═══════════════════════════════════════════════════════════════ */
s.cartCount = () => s.cart.length;
s.countOfType = (code) => s.cart.filter((l) => l.st === code).length;

// เอาทั้งชุด group ออกจากตะกร้า (ใช้ทั้งตอนกดเอาออก และตอนลด qty จนหมด)
const dropSet = (st, headCode) => {
	s.cart = s.cart.filter((l) => !(l.st === st && l.set === headCode));
};

/* ติ๊ก/เอาออก 1 รายการ — ไม่เรียก recompute เอง เพื่อให้ปุ่ม All กดทีเดียวแล้วค่อย recompute รอบเดียว
   🔴 3 ทางแยกตามกติกาชุด (C33) — ดูหัวข้อ "ชุดแม่-ลูก" ข้างบนก่อนแก้ */
const applyToggle = (row) => {
	/* 🔴 resolve เป็น master จากแคตตาล็อกก่อนเสมอ — แถวที่ติ๊กชีทส่งมาเป็น "สำเนา" ที่ copy มาบางฟิลด์
	   เคยพลาด 2026-08-30: สำเนาไม่มี `sub` ⇒ ติ๊กแม่ของชุด exclusive แล้วไม่เคลียลูกให้ (ฝั่งลูกทำงานปกติ
	   เพราะ `par` ถูก copy มา) ⇒ ใบมีทั้งแม่และลูก = เก็บเงินซ้ำ */
	const item = findMaster(s.st, row.c) || row;
	const head = groupHeadOf(s.st, item);

	/* ── ชุด group: กดที่ไหนก็ได้ในชุด = เข้า/ออกทั้งชุด · หัวชุดไม่เคยเข้าตะกร้า ── */
	if (head) {
		const kids = kidItems(s.st, head);
		if (!kids.length) return; // ลูกถูกปิดใช้งานหมดแล้ว — ชุดนี้สั่งไม่ได้ ปล่อยเงียบดีกว่าใส่ใบเปล่า
		const on = kids.every((kd) => inCart(keyOf(s.st, kd)) >= 0);
		if (on) {
			dropSet(s.st, head.c);
			// เผื่อบรรทัดเก่าที่ยังไม่มีธง `set` (ใบที่บันทึกก่อน normalizeSets ทำงาน)
			kids.forEach((kd) => {
				const at = inCart(keyOf(s.st, kd));
				if (at >= 0) s.cart.splice(at, 1);
			});
			return;
		}
		kids.forEach((kd) => {
			if (inCart(keyOf(s.st, kd)) >= 0) return;
			s.cart.push(mkSetLine(s.st, kd, head.c));
		});
		return;
	}

	const k = keyOf(s.st, item);
	const ix = inCart(k);
	if (ix >= 0) {
		s.cart.splice(ix, 1);
		return;
	}
	s.cart.push(mkLine(s.st, item));

	/* ── ชุด exclusive: เพิ่งใส่ตัวไหน อีกฝั่งต้องออก (แม่ XOR ลูก) ──
	   ไม่เคลีย = ใบมีทั้ง C1 ฿320 และลูกอีก ฿340 ⇒ เก็บเงินคนไข้ซ้ำ */
	if (setKind(item) !== 'x') return;
	if (item.par) {
		// ติ๊กลูก → เอาแม่ออก
		const at = inCart(keyOf(s.st, findMaster(s.st, item.par) || { c: item.par }));
		if (at >= 0) s.cart.splice(at, 1);
		return;
	}
	// ติ๊กแม่ → เอาลูกทุกตัวที่อยู่ในใบออก
	const kidCode = {};
	kidsOf(item).forEach((c) => {
		kidCode[c] = 1;
	});
	if (Object.keys(kidCode).length) s.cart = s.cart.filter((l) => !(l.st === s.st && kidCode[l.c]));
};

/* แถวนี้ถือว่าติ๊กอยู่ไหม — หัวชุด group ไม่เคยอยู่ในตะกร้า ⇒ ดูจาก "ลูกครบชุดหรือยัง" แทน
   ใช้ค่าเดียวกันทั้งกล่อง checkbox ในชีท ปุ่ม All และ toggleGroup ⇒ ตากับการกดตรงกันเสมอ */
s.rowOn = (item) => {
	const head = groupHeadOf(s.st, item);
	if (head) {
		const kids = kidItems(s.st, head);
		return kids.length > 0 && kids.every((kd) => inCart(keyOf(s.st, kd)) >= 0);
	}
	return inCart(keyOf(s.st, item)) >= 0;
};

s.toggleItem = (item) => {
	// ลูกติ๊กได้ทั้ง 2 กติกาแล้ว (C33) — group ดึงมาทั้งชุด · exclusive เคลียแม่ให้
	applyToggle(item);
	s.recompute();
};

// ปุ่ม All ที่หัวกลุ่ม — ครบทั้งกลุ่มแล้วกดอีกทีคือเอาออกทั้งกลุ่ม
/* กดหัวการ์ดชุด (หรือปุ่ม All ของการ์ดชุด) = เข้า/ออกทั้งชุด — ทางเดียวที่เลือกชุดได้
   ลูกในการ์ดไม่มี checkbox แล้ว (พี่สั่ง 08-30: "มันยังกดเพิ่มเองได้") */
s.toggleSet = (g) => {
	if (!g || !g.set) return;
	const head = findMaster(s.st, g.set.c);
	if (!head) return;
	applyToggle(head);
	s.recompute();
};

s.toggleGroup = (g) => {
	if (g && g.set) return s.toggleSet(g);
	/* ใช้ "แถวที่ไม่ใช่ลูก" เป็นตัวแทนของกลุ่ม — ครอบคลุมทั้ง 2 กติกาพอดี:
	     exclusive → กดที่แม่ ได้ราคาชุดซึ่งถูกกว่าไล่ติ๊กลูกทีละตัวเสมอ
	     group     → กดที่หัวชุด ได้ลูกครบชุด
	   ไล่ติ๊กลูกด้วยจะกลายเป็นเคลียกันไปมา (XOR) แล้วผลลัพธ์ขึ้นกับลำดับแถว */
	const rows = (g.rows || []).filter((i) => !isKid(i));
	if (!rows.length) return;
	const allOn = rows.every((i) => s.rowOn(i));
	// ครบแล้ว → เอาออกเฉพาะตัวที่อยู่ · ยังไม่ครบ → เติมเฉพาะตัวที่ยังไม่มี
	rows.forEach((i) => {
		if (allOn === s.rowOn(i)) applyToggle(i);
	});
	s.recompute();
};

// ปรับจำนวน — ลดจนเหลือ 0 คือเอาออกจากใบ (ปุ่มลบซ้ำๆ ไม่ควรทิ้งแถว qty 0 ค้างไว้)
s.setQty = (ix, d) => {
	const l = s.cart[ix];
	if (!l) return;
	// 🔴 is_one = เพิ่มไม่ได้ (ลดยังได้ เพราะลดจนเหลือ 0 คือเอาออกจากใบ)
	if (l.one && Number(d) > 0) return;
	const q = Number(l.qty || 1) + Number(d);
	if (q <= 0) {
		// ชุด group ลดจนหมด = ออกทั้งชุด — ทั้งชุดเจาะครั้งเดียว เหลือบางตัวคือใบที่ห้องแลปอ่านไม่ออก
		if (l.set) dropSet(l.st, l.set);
		else s.cart.splice(ix, 1);
	} else {
		l.qty = q;
		// 🔴 ชุด group จำนวนต้องเท่ากันทั้งชุด — ปรับที่บรรทัดไหนก็ลากพี่น้องตามไปด้วย
		if (l.set) {
			s.cart.forEach((x) => {
				if (x.set === l.set && x.st === l.st) x.qty = q;
			});
		}
	}
	s.recompute();
};

s.removeLine = (ix) => {
	const l = s.cart[ix];
	if (!l) return;
	// ชุด group: ลบบรรทัดไหนก็ออกทั้งชุด (พี่เคาะ 08-30) — ชุดที่ไม่ครบ ห้องแลปอ่านแล้วไม่รู้ว่าตกหล่นหรือตั้งใจ
	if (l.set) dropSet(l.st, l.set);
	else s.cart.splice(ix, 1);
	s.recompute();
};
s.clearCart = () => {
	s.cart = [];
	s.recompute();
};
// ล้างเฉพาะ section ที่เปิดอยู่ — ใบเดียวกันอาจมีของจาก section อื่นที่ยังต้องเก็บไว้
s.clearSec = () => {
	const data = s.cat[s.st];
	if (!data) return;
	const sec = s.sec[s.st];
	const ids = {};
	const codes = {}; // หัวชุดที่กำลังถูกล้าง — ลูกของชุด group ต้องไปด้วยแม้อยู่คนละ section
	data.items.filter((i) => i.sec === sec).forEach((i) => {
		ids[keyOf(s.st, i)] = 1;
		codes[i.c] = 1;
	});
	s.cart = s.cart.filter((l) => !ids[l.k] && !(l.set && codes[l.set] && l.st === s.st));
	s.recompute();
};

/* 🔴 claim = 0 เสมอ ไม่ใช่บั๊ก — master ทุกตัวมีแต่แถวราคา `STD` ไม่มีแถวตามสิทธิ์
      ⇒ api-cpoe-price-calc.js:186 ตกมาคิดชำระเองทั้งหมด (mockup ตั้ง claim = 0 ด้วยเหตุผลเดียวกัน)
      ห้ามคิดจาก `cover_price` — ตัวนั้นคือ "ถ้าสิทธิ์ครอบคลุมจะเบิกได้เท่าไร" ไว้โชว์ส่วนต่างต่อรายการ
      เอามาบวกเป็นยอดเบิกได้ = บอกหมอว่าคนไข้ไม่ต้องจ่าย ทั้งที่บิลจริงเก็บเต็ม
   ⛔ C13: เปลี่ยนมาใช้ยอดจาก process cpoe-price-calc แทน ไม่ใช่คิดเองในจอ */
s.totals = () => {
	let total = 0;
	s.cart.forEach((l) => {
		total += Number(l.p || 0) * Number(l.qty || 1);
	});
	const claim = 0;
	return { total: total, claim: claim, paid: total - claim };
};
// ส่วนต่างต่อรายการ — "ถ้าสิทธิ์ครอบคลุมจะเบิกได้เท่าไร" (ตัวเลขเทียบ ไม่ใช่ยอดจริง)
s.coverHint = (l) => (l && l.cv ? money(Number(l.cv) * Number(l.qty || 1)) : '');

/* ══ โหมด pick — กดเพิ่มทีละรายการ ════════════════════════════════════════
   ต่างจากติ๊กชีท: กดซ้ำ = เพิ่มจำนวน ไม่ใช่เอาออก (หัตถการ/บริการสั่งซ้ำหลายหน่วยได้จริง) */
s.addItem = (item) => {
	const k = keyOf(s.st, item);
	const ix = inCart(k);
	if (ix >= 0) {
		// 🔴 รายการที่ตั้ง is_one สั่งได้ครั้งละ 1 ชิ้น — กดซ้ำต้องไม่เพิ่มจำนวน
		if (s.cart[ix].one) {
			field.alert('“' + (item.n || item.c) + '” สั่งได้ครั้งละ 1 รายการเท่านั้น', 'warning');
			return;
		}
		s.cart[ix].qty = Number(s.cart[ix].qty || 1) + 1;
	} else s.cart.push(mkLine(s.st, item));
	s.recompute();
};

/* ══ สิ่งส่งตรวจ ══════════════════════════════════════════════════════════
   แถบสรุปหลอด — นับจากรายการที่ติ๊กไว้ทั้งใบ (ข้าม section) ตามหัวใบกระดาษ
   เป็นสิ่งที่ใบกระดาษมีแล้วแต่จอเดิมยังไม่มี (พยาบาลต้องรู้ว่าเจาะกี่หลอด หลอดอะไร) */
s.hasSpecBar = () => !!typeOf(s.st).spec;
s.specTubes = () => {
	const map = {};
	const order = [];
	// 🔴 ชุด group นับหลอดเดียวต่อชุด — ทั้งชุดเจาะครั้งเดียว นับทุกบรรทัด = พยาบาลเตรียมหลอดเกิน 4 เท่า
	s.cart.filter((l) => l.st === 'lab' && l.sp && isSetLead(l)).forEach((l) => {
		if (!map[l.sp]) {
			map[l.sp] = { code: l.sp, name: l.spn || l.sp, n: 0 };
			order.push(l.sp);
		}
		map[l.sp].n++;
	});
	return order.map((c) => map[c]);
};

// รายการที่ต้องระบุสิ่งส่งตรวจแต่ยังไม่ได้ระบุ — ตัวตัดสินว่าส่งใบได้ไหม
s.missSpec = () => s.cart.map((l, ix) => ({ l: l, ix: ix })).filter((x) => needSpec(x.l) && !(x.l.lab_data && x.l.lab_data.source));
s.needSpecOf = (l) => needSpec(l);

// input[type=datetime-local] ต้องการรูป YYYY-MM-DDTHH:mm ตามเวลาเครื่อง
const nowLocal = () => {
	const d = new Date();
	const pad = (n) => String(n).padStart(2, '0');
	return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + 'T' + pad(d.getHours()) + ':' + pad(d.getMinutes());
};
// วันนี้โชว์แค่เวลา · วันอื่นโชว์ DD/MM HH:mm (ปีไม่ช่วยตัดสินใจตรงนี้)
const shortAt = (v) => {
	if (!v) return '';
	const parts = String(v).split('T');
	const d = parts[0];
	const t = parts[1] || '';
	if (d === nowLocal().slice(0, 10)) return t;
	const seg = d.split('-');
	return (seg[2] + '/' + seg[1] + ' ' + t).trim();
};

// แถบใต้รายการในตะกร้า — เหลืองเมื่อยังไม่กรอก · เขียวพร้อมสรุปเมื่อกรอกแล้ว
s.specBar = (l) => {
	if (!needSpec(l)) return null;
	const d = l.lab_data;
	if (!d || !d.source) {
		return { done: false, text: 'ยังไม่ระบุสิ่งส่งตรวจ', title: l.sp ? l.sp + ' = ' + (l.spn || 'ไม่ระบุ') : 'รายการนี้ไม่ได้ผูกสิ่งส่งตรวจไว้', btn: 'ระบุ' };
	}
	const full = [d.source, STORAGE[d.storage] || d.storage, String(d.at || '').replace('T', ' '), d.by].filter(Boolean).join(' · ');
	const brief = [d.source, STORAGE_SHORT[d.storage] || d.storage, shortAt(d.at)].filter(Boolean).join(' · ');
	return { done: true, text: brief, title: full, btn: 'แก้' };
};

s.STORAGE_OPTS = [
	{ v: 'IM', label: STORAGE.IM },
	{ v: 'RF', label: STORAGE.RF },
	{ v: 'RT', label: STORAGE.RT },
];
s.openSpec = (ix) => {
	const l = s.cart[ix];
	if (!l) return;
	const d = l.lab_data || {};
	s.specForm = {
		source: d.source || '',
		storage: d.storage || 'IM',
		at: d.at || nowLocal(),
		// คนเก็บ default = แพทย์ผู้สั่ง (เคสปกติสุด) แต่แก้เป็นคนอื่นได้ — พยาบาลเป็นคนเจาะจริง
		by: d.by || s.docLabel(s.docList.find((x) => String(x.doctor_id) === String(s.docId))) || '',
	};
	s.specIx = ix;
};
s.closeSpec = () => {
	s.specIx = -1;
};
s.setSpecField = (k, v) => {
	const f = {};
	Object.keys(s.specForm).forEach((x) => {
		f[x] = s.specForm[x];
	});
	f[k] = v;
	s.specForm = f;
};
s.specTarget = () => (s.specIx >= 0 ? s.cart[s.specIx] : null);
s.saveSpec = () => {
	const l = s.cart[s.specIx];
	if (!l) return;
	// ไม่กรอก source = ยังไม่ถือว่าระบุ — ปุ่มส่งใบยังต้องปิดอยู่ (กติกาเดียวกับ missSpec)
	if (!String(s.specForm.source || '').trim()) return;
	l.lab_data = {
		source: String(s.specForm.source).trim(),
		storage: s.specForm.storage,
		at: s.specForm.at,
		by: s.specForm.by,
	};
	s.specIx = -1;
	s.recompute();
};

/* ══ ยาที่เคยรับ (prior_medication) ═══════════════════════════════════════
   ถามระดับใบ แต่ trigger มาจากรายการ — Section master ตัวไหนติ๊กธง `prior_medication` ไว้
   (ตอนนี้มี MY Mycology ตัวเดียว) ถ้าในใบมีรายการจาก section นั้น ถึงจะถาม */
s.pmSecs = () => {
	const seen = {};
	const out = [];
	s.cart.forEach((l) => {
		const block = s.cat[l.st];
		const sec = block && (block.sections || []).find((x) => x.code === l.sec);
		if (sec && sec.pm && !seen[sec.name]) {
			seen[sec.name] = 1;
			out.push(sec.name);
		}
	});
	// เอารายการ section นั้นออกหมดแล้ว คำตอบเดิมต้องไม่ค้างติดไปกับใบ (กล่องหาย = คำถามหายไปด้วย)
	if (!out.length && (s.priorMed || s.priorSpec)) {
		s.priorMed = '';
		s.priorSpec = '';
	}
	return out;
};
s.setPriorMed = (v) => {
	// กดซ้ำที่ตัวเดิม = ยกเลิกคำตอบ (ฟอร์มจริงไม่บังคับตอบ)
	s.priorMed = s.priorMed === v ? '' : v;
	if (s.priorMed !== '2') s.priorSpec = '';
};
s.setPriorSpec = (v) => {
	s.priorSpec = String(v == null ? '' : v);
};

/* ══ ประวัติการสั่ง ═══════════════════════════════════════════════════════
   ใบเก่าของผู้ป่วยรายนี้ **ทุกวิสิท** · process กรองรายการยาออกให้แล้วและบอกว่าซ่อนไปกี่บรรทัด
   🔴 สั่งซ้ำได้เฉพาะรายการที่ยังหาต้นทางใน catalog เจอ — ของที่ถูกปิดใช้งานต้องบอกให้เห็น ไม่ใช่เงียบ */
s.hist = [];
s.histLoading = false;
s.histErr = '';
s.histLoaded = false;
s.histOff = {}; // แถวที่ติ๊กออก (ไม่เอาตอนสั่งซ้ำ) — key ผูกกับใบด้วย เพราะรหัสเดียวกันโผล่ได้หลายใบ

const hKey = (ix, i) => ix + ':' + i.st + ':' + i.c;
// ใบเก่าเก็บแค่ item_code — ต้องหาตัวจริงใน catalog ก่อนจึงจะสั่งซ้ำได้
const findMaster = (st, code) => {
	const d = s.cat[st];
	return d ? d.items.find((i) => i.c === code) : null;
};

s.histRows = () =>
	s.hist.map((o, ix) => {
		const items = (o.items || []).map((i, ri) => {
			const master = findMaster(i.st, i.c);
			return {
				ri: ri,
				st: i.st,
				c: i.c,
				n: i.n,
				q: i.q,
				p: i.p,
				can: !!master,
				on: !!master && !s.histOff[hKey(ix, i)],
			};
		});
		const avail = items.filter((i) => i.can);
		const nOn = avail.filter((i) => i.on).length;
		return {
			ix: ix,
			no: o.no,
			at: o.at,
			status: o.status,
			vn: o.vn,
			n: o.n,
			hidden: o.hidden,
			total: o.total,
			paid: o.paid,
			items: items,
			hasAvail: avail.length > 0,
			allOn: avail.length > 0 && nOn === avail.length,
			nOn: nOn,
		};
	});

s.histToggleRow = (ix, i) => {
	const k = hKey(ix, i);
	const next = {};
	Object.keys(s.histOff).forEach((x) => {
		next[x] = s.histOff[x];
	});
	if (next[k]) delete next[k];
	else next[k] = 1;
	s.histOff = next;
};
s.histToggleAll = (row) => {
	const next = {};
	Object.keys(s.histOff).forEach((x) => {
		next[x] = s.histOff[x];
	});
	row.items.filter((i) => i.can).forEach((i) => {
		const k = hKey(row.ix, i);
		if (row.allOn) next[k] = 1;
		else delete next[k];
	});
	s.histOff = next;
};

/* สั่งซ้ำ — ดึงเฉพาะแถวที่ติ๊กไว้เข้าใบปัจจุบัน
   🔴 ดึงจาก master ไม่ใช่จากใบเก่า — ราคา/สิ่งส่งตรวจต้องเป็นของวันนี้ ไม่ใช่ของวันที่สั่งครั้งก่อน */
s.histAgain = (row) => {
	let added = 0;
	row.items.forEach((i) => {
		if (!i.can || !i.on) return;
		const master = findMaster(i.st, i.c);
		if (!master) return;
		const k = i.st + ':' + (master.id || master.c);
		const at = inCart(k);
		// 🔴 รายการ is_one คงไว้ที่ 1 เสมอ ไม่ว่าใบเก่าจะสั่งไว้กี่ชิ้น
		const one = master.one === true;
		if (at >= 0) {
			if (!one) s.cart[at].qty = Number(s.cart[at].qty || 1) + Number(i.q || 1);
		} else {
			s.cart.push(mkLine(i.st, master, { qty: one ? 1 : Number(i.q || 1) }));
		}
		added++;
	});
	if (!added) return;
	// ใบเก่าอาจมีทั้งแม่และลูกของชุด — จัดให้เข้ารูปก่อน ไม่งั้นลูกถูกคิดราคาซ้ำในยอดที่จอโชว์
	normalizeSets();
	field.alert('ดึงเข้าใบแล้ว ' + added + ' รายการ', 'success');
	s.recompute();
};

s.loadHistory = () => {
	if (s.histLoading || s.histLoaded) return;
	s.histLoading = true;
	s.histErr = '';
	const p = field.params || {};
	field.getFormRef().userState.runProcess(
		HISTORY_PROC,
		{ person_id: p.person_id || '', visit_id: p.visit_id || '' },
		(res) => {
			s.histLoading = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				s.histErr = 'อ่านประวัติไม่สำเร็จ: ' + (d.message || 'ไม่ทราบสาเหตุ');
				return;
			}
			s.hist = Array.isArray(d.orders) ? d.orders : [];
			s.histLoaded = true;
		},
		(err) => {
			s.histLoading = false;
			s.histErr = 'อ่านประวัติไม่สำเร็จ: ' + ((err && err.message) || err);
		}
	);
};

/* ══ ตัวเปลี่ยนสถานะจอ ════════════════════════════════════════════════════ */
s.setType = (code) => {
	s.st = code;
	s.prioOpen = false;
	// ประวัติโหลดตอนกดเข้าแท็บครั้งแรกเท่านั้น — คนส่วนใหญ่เปิดจอมาเพื่อสั่ง ไม่ได้มาดูของเก่า
	if (code === HISTORY.code) s.loadHistory();
	s.recompute();
};
s.pickSec = (code) => {
	// ระหว่างค้น ผลลัพธ์รวมทุก section อยู่แล้ว — คลิกแถบซ้ายจึงเป็น "พาไปดู" ไม่ใช่เปลี่ยนหน้า
	// (เฉพาะติ๊กชีท — โหมด pick เป็นลิสต์เดียวไม่มี anchor ให้กระโดด)
	if (s.mode() === 'sheet' && String(s.q[s.st] || '').trim()) {
		/* 🔴 ต้องเป็น `globalThis.document` ห้ามเขียน `document` เฉยๆ
		   `document` อยู่ใน restricted ของ compileFn (initcraft/src/utils/Util.ts:19) ⇒ ถูก shadow เป็น undefined
		   เขียนตรงๆ จะ throw "Cannot read properties of undefined" แล้วจอแดงทั้งใบ (เจอตอน render preview 08-30)
		   globalThis ไม่ได้อยู่ในลิสต์ จึงเป็นทางเดียวที่แตะ DOM ได้จาก event ของฟอร์ม */
		const doc = globalThis.document;
		const el = doc && doc.getElementById ? doc.getElementById('cpoe-sec-' + code) : null;
		if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
		return;
	}
	s.sec[s.st] = code;
	// คนละ section คนละชุดกลุ่ม — ค้างกลุ่มเก่าไว้จะเปิดมาเจอจอว่างโดยไม่รู้ว่าถูกกรองอยู่
	s.grp[s.st] = '';
	s.bp[s.st] = '';
	s.recompute();
};
s.setQ = (v) => {
	s.q[s.st] = String(v == null ? '' : v);
	s.recompute();
};
s.clearQ = () => s.setQ('');
s.qNow = () => String(s.q[s.st] || '');

s.setGrp = (v) => {
	s.grp[s.st] = v;
	s.bp[s.st] = ''; // เปลี่ยนกลุ่ม = ส่วนย่อยของกลุ่มเดิมใช้ต่อไม่ได้
	s.recompute();
};
s.setBp = (v) => {
	s.bp[s.st] = v;
	s.recompute();
};

s.setPrio = (v) => {
	s.prio = v;
	s.prioOpen = false;
};
s.togglePrioMenu = () => {
	s.prioOpen = !s.prioOpen;
};
s.closePrioMenu = () => {
	s.prioOpen = false;
};
s.prioCurrent = () => PRIORITY.find((p) => p.v === s.prio) || PRIORITY[0];
s.prioInMore = () => s.PRIORITY_MORE.some((p) => p.v === s.prio);
// ปุ่ม "อื่นๆ" ต้องเปลี่ยนหน้าเป็นค่าที่เลือก ไม่งั้นเห็นแค่คำว่า "อื่นๆ" แล้วไม่รู้ว่าใบนี้ด่วนระดับไหน
s.prioMoreLabel = () => (s.prioInMore() ? s.prioCurrent().label : 'อื่นๆ');
s.prioMoreCls = () => (s.prioInMore() ? s.prioCurrent().cls : '');

/* ══ ประกอบภาพของจอ — ยกกติกามาจาก renderSheet/renderGroupBar ของ mockup ══ */
s.recompute = () => {
	const st = s.st;
	const data = s.cat[st];
	if (!data) {
		s.view = { rail: [], groups: [], head: { title: '', sub: '' }, fbar: null, empty: false, pick: null };
		return;
	}
	const q = String(s.q[st] || '').trim();
	const sec = s.sec[st];

	const picked = {};
	s.cart.filter((l) => l.st === st).forEach((l) => {
		picked[l.k] = 1;
	});

	/* ── โหมดเลือกทีละรายการ (หัตถการ · บริการอื่นๆ) ────────────────────
	   ต่างจากติ๊กชีท 3 อย่าง: ดูรวมทุก section ได้ ('' = ทั้งหมด) · ไม่จัดกลุ่มเป็นการ์ด
	   · ตัดที่ PICK_LIMIT แถว (order มี 4,350 รายการ เลื่อนดูจบไม่ไหว ต้องพิมพ์ค้น) */
	if (typeOf(st).mode === 'pick') {
		const hitPick = (i) => (i.n + ' ' + i.c).toLowerCase().indexOf(q.toLowerCase()) >= 0;
		const all = q ? data.items.filter(hitPick) : sec ? data.items.filter((i) => i.sec === sec) : data.items;
		const nFound = all.length;
		const rows = all.slice(0, PICK_LIMIT).map((i) => {
			const secOfRow = data.sections.find((x) => x.code === i.sec);
			return {
				id: i.id,
				c: i.c,
				n: i.n,
				p: i.p,
				cv: i.cv,
				sp: i.sp,
				spn: i.spn,
				sec: i.sec,
				one: i.one === true,
				secName: (secOfRow && secOfRow.name) || '',
				_k: keyOf(st, i),
				_on: !!picked[keyOf(st, i)],
				_hl: hlParts(i.n, q),
			};
		});
		const hitsPick = {};
		if (q) all.forEach((i) => {
			hitsPick[i.sec] = (hitsPick[i.sec] || 0) + 1;
		});
		// section เดียวไม่ต้องมีแถบให้เลือก — กดแล้วได้ของเท่าเดิม
		const showRail = data.sections.length > 1;
		const railPick = !showRail
			? []
			: [{ code: '', name: '', label: 'ทั้งหมด', cur: !q && !sec, dim: false, tailCls: 'tot', tail: data.items.length }].concat(
					data.sections.map((x) => {
						const nPick = data.items.filter((i) => i.sec === x.code && picked[keyOf(st, i)]).length;
						const nHit = hitsPick[x.code] || 0;
						return {
							code: x.code,
							name: x.name,
							label: x.code,
							cur: !q && x.code === sec,
							dim: !!q && !nHit,
							tailCls: q ? (nHit ? 'hit' : 'tot') : nPick ? 'pick' : 'tot',
							tail: q ? (nHit ? nHit : x.n) : nPick ? nPick : x.n,
						};
					})
			  );
		const secCur = data.sections.find((x) => x.code === sec);
		const label = q
			? 'ผลค้นหา “' + q + '” · ' + nFound + ' รายการ' + (Object.keys(hitsPick).length ? ' ใน ' + Object.keys(hitsPick).length + ' section' : '')
			: sec
			? sec + ' · ' + ((secCur && secCur.name) || '') + ' · ' + nFound + ' รายการ'
			: nFound + ' รายการ';
		s.view = {
			rail: [],
			groups: [],
			head: { title: '', sub: '' },
			fbar: null,
			empty: false,
			pick: {
				showRail: showRail,
				rail: railPick,
				rows: rows,
				label: label + (nFound > PICK_LIMIT ? ' · แสดง ' + PICK_LIMIT + ' แรก พิมพ์ค้นเพื่อกรอง' : ''),
				empty: !rows.length,
			},
		};
		return;
	}


	const secIx = {};
	data.sections.forEach((x, i) => {
		secIx[x.code] = i;
	});
	const secName = (c) => (data.sections.find((x) => x.code === c) || {}).name || c;
	const gName = (c) => ((data.groups || []).find((g) => g.code === c) || {}).name || c;

	const ql = q.toLowerCase();
	const hit = (i) => (i.n + ' ' + i.c + ' ' + (i.lc || '')).toLowerCase().indexOf(ql) >= 0;

	// 🔴 ค้นแล้วต้องเห็นทุก section ไม่ใช่แค่อันที่เปิดอยู่ — ชื่อเทสต์คนสั่งจำได้ แต่ section จำไม่ได้
	//    (เคยทำกรองแค่ section ที่เปิด แล้วพี่ตีกลับ)
	/* 🔴 ค้นเจอ "ลูก" ต้องลากแม่มาแสดงด้วย (spec §7.5 ข้อ 3) — ลูกไม่มี checkbox ของตัวเอง
	   โชว์แต่ลูก = หมอเห็นชื่อที่ค้นเจอแต่ไม่มีทางสั่ง (ค้น "Sodium" ต้องเจอ Electrolyte ที่เป็นทางสั่ง) */
	const withParents = (rows) => {
		const have = {};
		rows.forEach((i) => {
			have[i.c] = 1;
		});
		const extra = [];
		rows.forEach((i) => {
			if (!i.par || have[i.par]) return;
			const p = data.items.find((x) => x.c === i.par);
			if (!p) return;
			have[p.c] = 1;
			extra.push(p);
		});
		return extra.length ? rows.concat(extra) : rows;
	};
	const secItems = q ? withParents(data.items.filter(hit)) : data.items.filter((i) => i.sec === sec);

	// แถบกรองกลุ่ม (xray) ใช้เฉพาะตอนไม่ได้ค้น — ระหว่างค้นผลลัพธ์ข้าม section อยู่แล้ว
	// ถ้ากรองกลุ่มซ้อนอีก คนค้นจะไม่เห็นตัวที่พิมพ์ถูกแล้วแต่อยู่คนละกลุ่ม
	const useF = !q && !!data.groups;
	const fg = useF ? s.grp[st] || '' : '';
	const fb = useF ? s.bp[st] || '' : '';
	const items = !useF
		? secItems
		: secItems.filter((i) => (!fg || (fg === 'rest' ? !i.bv : i.gv === fg)) && (!fb || i.bv === fb));

	/* ── แถบ section ซ้าย ─────────────────────────────────────────────── */
	const hits = {};
	if (q) items.forEach((i) => {
		hits[i.sec] = (hits[i.sec] || 0) + 1;
	});
	const rail = data.sections.map((x) => {
		const nPick = data.items.filter((i) => i.sec === x.code && picked[keyOf(st, i)]).length;
		const nHit = hits[x.code] || 0;
		return {
			code: x.code,
			name: x.name,
			dim: !!q && !nHit,
			cur: !q && x.code === sec,
			tailCls: q ? (nHit ? 'hit' : 'tot') : nPick ? 'pick' : 'tot',
			tail: q ? (nHit ? nHit : x.n) : nPick ? nPick : x.n,
		};
	});

	/* ── การ์ดกลุ่ม ────────────────────────────────────────────────────
	   ปกติแบ่งด้วย lab_group · ระหว่างค้นแบ่งด้วย section ก่อนแล้วค่อยกลุ่ม
	   (ไม่งั้นผลจากคนละ section ปนกันจนไม่รู้ว่าเทสต์ตัวไหนอยู่แลปไหน)

	   🔴 **ชุด group (`sub_order`) ได้การ์ดของตัวเอง แยกออกจากการ์ด lab_group** (พี่สั่ง 2026-08-30)
	      เพราะทั้งชุดสั่งพร้อมกันเสมอ ⇒ ทั้งการ์ดคือ "1 ตัวเลือก" ไม่ใช่รายการที่ติ๊กทีละแถว
	      อยู่ปนในการ์ดกลุ่มแล้วลูกมี checkbox = ตาเห็นว่า "กดเพิ่มทีละตัวได้" ซึ่งขัดกับกติกา
	      ⇒ ลูกในการ์ดนี้ไม่มี checkbox · เลือก/เอาออกที่หัวการ์ดหรือปุ่ม All ที่เดียว */
	const setKeyOf = (i) => {
		const head = groupHeadOf(st, i);
		return head ? 'set:' + head.c : '';
	};
	/* แนบ _k/_on/_hl ไว้กับ "สำเนา" ของแถว — ไม่แตะ object ในแคตตาล็อกที่ใช้ร่วมกันทุกรอบ */
	const mkRow = (i) => ({
		id: i.id,
		c: i.c,
		n: i.n,
		p: i.p,
		cv: i.cv,
		sp: i.sp,
		spn: i.spn,
		sec: i.sec,
		one: i.one === true,
		/* ชุดแม่-ลูก (C33): par = อยู่ในชุดของใคร · sk = กติกาของชุด ('x' exclusive · 'g' group)
		   setN = ชุดนี้มีลูกกี่ตัว (ป้าย "ชุด N รายการ" บนแม่ของชุด exclusive)
		   inset = อยู่ในการ์ดชุด ⇒ เทมเพลตวาดเป็น div ไม่มี checkbox (เลือกที่หัวการ์ด) */
		par: i.par || '',
		sk: i.sk || '',
		setN: kidItems(st, i).length,
		inset: !!setKeyOf(i),
		_k: keyOf(st, i),
		_on: !!picked[keyOf(st, i)],
		_hl: hlParts(i.n, q),
	});

	const gmap = {};
	const gorder = [];
	items.forEach((i) => {
		const sk = setKeyOf(i);
		const gk = sk ? (q ? i.sec + '|' + sk : sk) : q ? i.sec + '|' + (i.g || '') : i.g || '';
		if (!gmap[gk]) {
			const head = sk ? groupHeadOf(st, i) : null;
			const gLabel = head ? head.n : i.g || (q ? '' : 'ไม่ได้จัดกลุ่ม');
			gmap[gk] = {
				gk: gk,
				sec: i.sec,
				/* การ์ดชุด — เก็บ code/ราคา/จำนวนลูกไว้ที่หัวการ์ด แทนที่จะมีแถวหัวชุดในตัวการ์ด */
				set: head ? { c: head.c, id: head.id, p: head.p, n: kidItems(st, head).length } : null,
				// xray ตอนดู "ทุกกลุ่ม" ต้องบอกด้วยว่าส่วนนี้อยู่กลุ่มไหน (Head & Neck › skull)
				// พอเลือกกลุ่มแล้วตัดออก — แถบกรองด้านบนบอกอยู่แล้ว ไม่ต้องซ้ำทุกการ์ด
				prefix: useF && !fg && i.gv ? gName(i.gv) : '',
				secCode: q ? i.sec : '',
				secName: q ? secName(i.sec) : '',
				label: gLabel,
				// การ์ดชุดเรียงตาม lab_group ของแม่ +0.5 ⇒ แทรกอยู่ถัดจากกลุ่มที่มันสังกัด ไม่ลอยไปท้ายชีท
				sort: (q ? (secIx[i.sec] === undefined ? 99 : secIx[i.sec]) * 1e6 : 0) +
					(i.g ? (i.gs == null ? 999 : i.gs) : 1e5) + (setKeyOf(i) ? 0.5 : 0),
				rows: [],
			};
			gorder.push(gk);
		}
		// หัวชุดขึ้นเป็น "หัวการ์ด" แล้ว ไม่ต้องมีแถวของตัวเองอีก (ไม่งั้นชื่อชุดขึ้น 2 ที่)
		//    ลูกของการ์ดชุดเติมทีเดียวทั้งชุดหลังลูปนี้ (ดู §เติมลูกให้การ์ดชุด) ⇒ ข้ามที่นี่ด้วย
		if (sk) return;
		gmap[gk].rows.push(mkRow(i));
	});

	/* ── เติมลูกให้การ์ดชุดให้ครบเสมอ ─────────────────────────────────
	   🔴 ต้องเอาลูกจาก master ไม่ใช่จาก `items` ที่กรองมา — ตอนค้นหา คำค้นอาจตรงกับแม่อย่างเดียว
	      (ค้น "Electrolyte" เจอแต่แม่) แล้วการ์ดจะโชว์แต่หัว ไม่มีรายการข้างใน
	      และ `setOn` ที่นับจากแถวก็จะเป็น false ตลอด ⇒ ปุ่มไม่ขึ้น ✓ ทั้งที่ลูกอยู่ในใบครบแล้ว */
	gorder.forEach((gk) => {
		const g = gmap[gk];
		if (!g.set) return;
		const head = findMaster(st, g.set.c);
		g.rows = kidItems(st, head).map(mkRow);
	});

	/* ── จัดลูกให้ต่อท้ายแม่ทันที (C31) ────────────────────────────────
	   เรียงตาม item_code อย่างเดียว จะมีรายการอื่นแทรกกลางชุด (C3-R โผล่ระหว่าง C3 กับ C5.1)
	   แล้วชุดดูขาดเป็นท่อน · ตอนค้นหายิ่งชัด เพราะแม่ที่ลากมาไปต่อท้ายสุด ห่างจากลูกที่ค้นเจอ
	   ลูกที่แม่ไม่ได้อยู่ในกลุ่มนี้ = อยู่ที่เดิม (ยังมีป้าย "อยู่ในชุด" บอกอยู่แล้ว) */
	const orderKin = (rows) => {
		const hasCode = {};
		rows.forEach((r) => {
			hasCode[r.c] = 1;
		});
		const kidsBy = {};
		let any = false;
		rows.forEach((r) => {
			if (!r.par || !hasCode[r.par]) return;
			(kidsBy[r.par] = kidsBy[r.par] || []).push(r);
			any = true;
		});
		if (!any) return rows;
		const out = [];
		rows.forEach((r) => {
			if (r.par && hasCode[r.par]) return; // ตามไปอยู่ท้ายแม่แทน
			out.push(r);
			(kidsBy[r.c] || []).forEach((k) => out.push(k));
		});
		return out;
	};

	const seenSec = {};
	const groups = gorder
		.map((gk) => gmap[gk])
		.sort((a, b) => a.sort - b.sort)
		.map((g) => {
			// กลุ่มแรกของแต่ละ section ได้ anchor ไว้ให้แถบซ้ายกระโดดมาหา
			const anchor = q && !seenSec[g.sec] ? 'cpoe-sec-' + g.sec : '';
			seenSec[g.sec] = 1;
			/* การ์ดชุด: "ติ๊กอยู่" = ลูกครบทุกตัวในการ์ด — ไม่มีแถวไหนติ๊กเดี่ยวได้ ⇒ ครบหรือไม่ครบเท่านั้น
			   (ลูกที่ถูกปิดใช้งานไปแล้วไม่โผล่ในการ์ด ⇒ นับจากแถวที่เห็นจริง ไม่ใช่จาก sub_order) */
			const setOn = g.set ? g.rows.length > 0 && g.rows.every((i) => i._on) : false;
			return {
				gk: g.gk,
				anchor: anchor,
				prefix: g.prefix,
				secCode: g.secCode,
				secName: g.secName,
				label: g.label,
				set: g.set ? { c: g.set.c, id: g.set.id, p: g.set.p, n: g.set.n, on: setOn } : null,
				big: g.rows.length > BIG_GROUP,
				/* ปุ่ม All นับเฉพาะแถวที่เป็น "ตัวแทนของชุด" (ไม่ใช่ลูก) — ตรงกับ s.toggleGroup เป๊ะ
				   ไม่งั้นปุ่มขึ้นว่าครบแล้วแต่กดอีกทีไม่เกิดอะไร (หรือกลับกัน)
				   กลุ่มที่มีแต่แถวลูกต้องไม่ขึ้นว่า "ครบแล้ว" (every ของ array ว่างคืน true) */
				allOn: g.set ? setOn : g.rows.some((i) => !i.par) && g.rows.filter((i) => !i.par).every((i) => i._on),
				rows: orderKin(g.rows),
			};
		});

	/* ── หัวชีท ───────────────────────────────────────────────────────── */
	const secObj = data.sections.find((x) => x.code === sec) || { name: '', n: 0 };
	const nPicked = data.items.filter((i) => i.sec === sec && picked[keyOf(st, i)]).length;
	const nSec = Object.keys(hits).length;
	const head = q
		? {
				title: 'ผลค้นหา',
				sub: '“' + q + '” · ' + items.length + ' รายการ' + (nSec ? ' ใน ' + nSec + ' section' : ''),
				canClearSec: false,
		  }
		: {
				title: secObj.name,
				// กรองอยู่ต้องบอกว่าเหลือกี่ตัวจากทั้งหมด ไม่งั้นเลขหัวกับของที่เห็นไม่ตรงจนงง
				sub:
					secObj.n +
					' รายการ' +
					(useF && (fg || fb) ? ' · กรองเหลือ ' + items.length : '') +
					(nPicked ? ' · ติ๊กแล้ว ' + nPicked : ''),
				canClearSec: nPicked > 0,
		  };

	/* ── แถบกรองกลุ่ม X-ray (2 ชั้น) ───────────────────────────────────
	   นับจาก section ที่เปิดอยู่เท่านั้น และตัด chip ที่ไม่มีรายการทิ้ง — กดแล้วเจอหน้าว่างคือ dead end */
	let fbar = null;
	if (useF) {
		const nBy = {};
		const pkBy = {};
		secItems.forEach((i) => {
			const k = i.gv || 'rest';
			nBy[k] = (nBy[k] || 0) + 1;
			if (picked[keyOf(st, i)]) pkBy[k] = (pkBy[k] || 0) + 1;
		});
		const gs = (data.groups || []).filter((g) => nBy[g.code]);
		const nRest = nBy.rest || 0;
		if (gs.length || nRest) {
			const row1 = [{ v: '', label: 'ทั้งหมด', n: secItems.length, pk: 0, on: fg === '', rest: false }]
				.concat(gs.map((g) => ({ v: g.code, label: g.name, n: nBy[g.code], pk: pkBy[g.code] || 0, on: fg === g.code, rest: false })))
				// รายการที่ยังไม่มีใครจัดกลุ่มต้องยังหยิบได้ ไม่ใช่หายไปจากจอเพราะไม่มีกลุ่ม
				.concat(nRest ? [{ v: 'rest', label: 'ยังไม่ได้จัดกลุ่ม', n: nRest, pk: pkBy.rest || 0, on: fg === 'rest', rest: true }] : []);

			// ชั้น 2 โผล่เฉพาะตอนเลือกกลุ่มจริง — 'ทั้งหมด'/'ยังไม่ได้จัดกลุ่ม' ไม่มีส่วนย่อยให้ไล่
			let row2 = null;
			const cur = gs.find((g) => g.code === fg);
			if (cur) {
				const inG = secItems.filter((i) => i.gv === cur.code);
				const bN = {};
				const bPk = {};
				inG.forEach((i) => {
					if (!i.bv) return;
					bN[i.bv] = (bN[i.bv] || 0) + 1;
					if (picked[keyOf(st, i)]) bPk[i.bv] = (bPk[i.bv] || 0) + 1;
				});
				const bps = cur.bps.filter((b) => bN[b.code]);
				// ส่วนย่อยตัวเดียวไม่ต้องมีแถบให้กด — กดแล้วได้ของเท่าเดิม
				if (bps.length > 1) {
					row2 = [{ v: '', label: 'ทั้งกลุ่ม', n: inG.length, pk: 0, on: fb === '' }].concat(
						bps.map((b) => ({ v: b.code, label: b.name, n: bN[b.code], pk: bPk[b.code] || 0, on: fb === b.code }))
					);
				}
			}
			fbar = { row1: row1, row2: row2 };
		}
	}

	s.view = { rail: rail, groups: groups, head: head, fbar: fbar, empty: !groups.length, pick: null };
};

/* ══ แคตตาล็อก ═══════════════════════════════════════════════════════════
   🔴 ยิงครั้งเดียวต่อการเปิดจอ (payload ~250KB) · สลับแท็บ/section ห้ามเรียกซ้ำ */
s.loadCatalog = () => {
	if (s.catLoading || s.catLoaded) return;
	s.catLoading = true;
	s.catErr = '';
	field.getFormRef().userState.runProcess(
		CATALOG_PROC,
		{ service_types: TYPES.map((t) => t.code) },
		(res) => {
			s.catLoading = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				// process ตีกลับพร้อมเหตุผล — โชว์ของจริง ไม่กลบด้วยข้อความกลางๆ
				s.catErr = 'โหลดแคตตาล็อกไม่สำเร็จ: ' + (d.message || 'ไม่ทราบสาเหตุ');
				return;
			}
			s.cat = d.catalog || {};
			s.catCounts = d.counts || {};
			s.catLoaded = true;
			TYPES.forEach((t) => {
				const block = s.cat[t.code] || { sections: [], items: [] };
				s.q[t.code] = '';
				s.sec[t.code] = t.mode === 'sheet' ? defaultSection(block.sections) : '';
				s.grp[t.code] = '';
				s.bp[t.code] = '';
			});
			s.recompute();
			// 🔴 ต้องหลังแคตตาล็อกพร้อมเท่านั้น — ใบเก็บแค่ id/code จอเติมที่เหลือจากแคตตาล็อก
			s.loadOrder();
		},
		(err) => {
			s.catLoading = false;
			s.catErr = 'โหลดแคตตาล็อกไม่สำเร็จ: ' + ((err && err.message) || err);
		}
	);
};

/* ══ บันทึก / ส่งใบ (C13) ═════════════════════════════════════════════════
   ใช้ process ตัวเดียวกับจอสั่งยา — `cpoe-order-save` แล้วต่อด้วย `cpoe-order-send` เมื่อกดส่ง
   🔴 จอไม่คิดราคาเอง · ไม่ออกเลขใบเอง · ไม่ตัดสินห้องปลายทางเอง — ฝั่ง process ทำทั้งหมด
   🔴 ส่ง `service_type` ราย "บรรทัด" ไปด้วยเสมอ (spec §3.4) — ใบเดียวมีหลายชนิดได้
      ส่วน service_type ของ "ใบ" = ชนิดของรายการแรก ใช้ออก prefix เลขที่ใบเท่านั้น */
s.saving = false;
s.savedOrderId = '';
s.savedOrderNumber = '';

const notifySaved = () => {
	// บอกฟอร์มแม่ว่าใบใน DB ขยับแล้ว — การ์ดหน้า EMR จะได้โหลดใหม่ตอนปิด popup
	const cb = (field.params || {}).on_order_saved;
	if (typeof cb === 'function') cb();
};

/* สิ่งส่งตรวจของบรรทัด — ทุกบรรทัดในชุด group ใช้ของบรรทัดแรกของชุด (เจาะครั้งเดียว จอถามที่เดียว)
   ไม่ส่งต่อ = ห้องแลปได้บรรทัดที่ไม่มีสิ่งส่งตรวจ แล้วไม่รู้ว่าต้องเก็บจากหลอดไหน */
const labDataOfLine = (l) => {
	const ix = setLeadIx(l);
	const src = ix >= 0 ? s.cart[ix] : l;
	return src.lab_data || null;
};

const payloadLines = () =>
	s.cart.map((l, i) => ({
		uid: l.k || 'l' + i,
		item_source: 'item',
		item_form_id: FORM_ITEM_MASTER,
		item_data_id: String(l.id || ''),
		item_code: l.c || '',
		item_name: l.n || '',
		quantity: Number(l.qty) || 1,
		// ชนิดของบรรทัดนี้ — ตัวจริงที่ห้องปลายทางใช้กรอง
		service_type: l.st,
		/* สิ่งส่งตรวจ — ส่ง by_id ไปด้วย เพราะ specimen_by เป็น select-data (Object)
		   process resolve ชื่อจาก core_user เอง ไม่เชื่อ label ที่จอส่ง */
		lab_data: (() => {
			const d = labDataOfLine(l);
			return d ? Object.assign({}, d, { by_id: d.by_id || s.docId || '' }) : null;
		})(),
	}));

const savePayload = () => {
	const ins = s.insCurrent();
	return {
		order_id: s.savedOrderId || String((field.params || {}).order_id || ''),
		visit_id: String((field.params || {}).visit_id || ''),
		// prefix เลขที่ใบ = ชนิดของรายการแรกในใบ (design §D4.1)
		service_type: s.cart.length ? s.cart[0].st : 'lab',
		inscl: ins ? { main: ins.main, sub: ins.sub } : null,
		inscl_row: ins ? { inscl_item_main: { value: ins.main, label: ins.label }, inscl_item_sub: { value: ins.sub, label: '' } } : null,
		cosign_user_id: String(s.docId || ''),
		priority: String(s.prio || '1'),
		prior_medication: String(s.priorMed || ''),
		prior_specify: String(s.priorSpec || ''),
		lines: payloadLines(),
		order_comment: '',
		order_tags: [],
	};
};

// then = ทำอะไรต่อหลังบันทึกสำเร็จ (ปิดจอ หรือส่งใบต่อ)
const doSave = (then) => {
	if (s.saving || !s.cart.length) return;
	s.saving = true;
	field.getFormRef().userState.runProcess(
		SAVE_PROC,
		savePayload(),
		(res) => {
			const d = (res && res.data) || {};
			// 🔴 process ที่ตีกลับด้วย success:false ก็มาทาง callback นี้ (ไม่ใช่ errCb) — ต้องเช็คเอง
			if (!d.success) {
				/* ล้มกลางทาง (หัวใบเกิดแล้วแต่รายการไม่ครบ) process คืน order_id มาด้วย —
				   ต้องจำไว้ ไม่งั้นกดใหม่จะได้ใบร่างใบที่สองค้างในระบบทั้งที่หมอตั้งใจสั่งใบเดียว */
				if (d.order_id) {
					s.savedOrderId = String(d.order_id);
					s.savedOrderNumber = String(d.order_number || '');
					notifySaved();
				}
				s.saving = false;
				const bad = Array.isArray(d.invalid_lines) ? d.invalid_lines : [];
				const detail = bad.length ? ' — ' + bad.map((b) => (b.item_name || b.uid) + ': ' + b.reason).join(' · ') : '';
				field.alert((d.message || 'บันทึกใบไม่สำเร็จ') + detail, 'warning');
				return;
			}
			s.savedOrderId = String(d.order_id || '');
			s.savedOrderNumber = String(d.order_number || '');
			notifySaved();
			if (typeof then === 'function') {
				then();
				return;
			}
			s.saving = false;
			field.alert('บันทึกใบ ' + (s.savedOrderNumber || '') + ' แล้ว (' + s.cart.length + ' รายการ)', 'success');
			field.getFormRef().closePopup();
		},
		(err) => {
			s.saving = false;
			field.alert('บันทึกใบไม่สำเร็จ: ' + ((err && err.message) || err), 'error');
		}
	);
};

s.saveDraft = () => doSave(null);

/* ส่งใบ = บันทึกก่อนแล้วค่อยส่ง — ห้องปลายทางต้องได้ใบที่ตรงกับตะกร้าล่าสุดเสมอ
   🔴 ห้องปลายทางไม่ได้เลือกที่จอนี้ — process หาเองจาก mapping ที่ห้องนั้นตั้งไว้ */
s.sendOrder = () => {
	if (s.missSpec().length) return; // ปุ่มปิดอยู่แล้ว — กันเส้นทางอื่นที่เรียกตรง
	doSave(() => {
		field.getFormRef().userState.runProcess(
			SEND_PROC,
			{ order_id: s.savedOrderId },
			(res) => {
				s.saving = false;
				const d = (res && res.data) || {};
				if (!d.success) {
					// ส่งไม่ผ่านแต่ใบบันทึกแล้ว — ต้องบอกให้ชัดว่าใบยังอยู่ ไม่ใช่หายไป
					field.alert('บันทึกใบ ' + (s.savedOrderNumber || '') + ' แล้ว แต่ส่งไม่สำเร็จ: ' + (d.message || 'ไม่ทราบสาเหตุ') + ' — ใบยังเป็นร่าง แก้แล้วส่งใหม่ได้', 'warning');
					return;
				}
				field.alert('ส่งใบ ' + (s.savedOrderNumber || '') + ' แล้ว', 'success');
				field.getFormRef().closePopup();
			},
			(err) => {
				s.saving = false;
				field.alert('บันทึกแล้วแต่ส่งไม่สำเร็จ: ' + ((err && err.message) || err), 'error');
			}
		);
	});
};

/* ══ ปิดจอ ═══════════════════════════════════════════════════════════════
   ฟอร์มแม่ใส่ cancelCallback เอง (ทับ default) แล้ว subFormClose() ให้ ⇒ ที่นี่ปิดอย่างเดียวพอ */
s.closeScreen = () => {
	field.getFormRef().closePopup();
};

/* ══ เปิดใบร่างเดิมมาแก้ ═══════════════════════════════════════════════════
   🔴 ไม่โหลดกลับ = หมอกดแก้ใบแล้วเห็นตะกร้าว่าง กดบันทึกได้ใบร่าง**ใบที่สอง**
      ซึ่งเป็นปัญหาเดียวกับที่การ์ดในหน้า EMR เกิดมาแก้ (ใบร่างซ้อนกันจนไม่รู้ว่าใบไหนจริง)
   🔴 ต้องรอแคตตาล็อกโหลดเสร็จก่อน — บรรทัดในใบเก็บแค่ id/code/ชื่อ/ราคา
      ส่วนสิ่งส่งตรวจ · ยอดเบิกได้ · section ต้องเติมจากแคตตาล็อก (ของที่ "ใช้แก้ต่อ" ไม่ใช่ของที่อยู่ในใบ) */
s.loadingOrder = false;
s.orderErr = '';
s.loadedOrderId = '';

// หา master จากแคตตาล็อกด้วย _id ก่อน (แม่นสุด) ไม่เจอค่อยตกมาที่ item_code
const masterOf = (st, dataId, code) => {
	const d = s.cat[st];
	if (!d) return null;
	const byId = dataId ? d.items.find((i) => String(i.id) === String(dataId)) : null;
	if (byId) return byId;
	return code ? d.items.find((i) => i.c === code) : null;
};

s.loadOrder = () => {
	const p = field.params || {};
	const id = String(p.order_id || '');
	if (!id || s.loadingOrder || s.loadedOrderId === id) return;
	s.loadingOrder = true;
	s.orderErr = '';
	field.getFormRef().userState.runProcess(
		GET_PROC,
		{ order_id: id, visit_id: String(p.visit_id || '') },
		(res) => {
			s.loadingOrder = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				s.orderErr = d.message || 'เปิดใบเดิมไม่สำเร็จ';
				field.alert(s.orderErr, 'error');
				return;
			}
			const o = d.order || {};
			/* ใบที่ไม่ใช่ร่างแล้ว เปิดดูได้แต่บันทึกทับไม่ได้ (process ฝั่งบันทึกก็ตีกลับอยู่แล้ว)
			   บอกตั้งแต่ตอนเปิด ดีกว่าให้หมอติ๊กเสร็จแล้วค่อยเจอตอนกดบันทึก */
			if (!o.can_edit) field.alert('ใบ ' + (o.order_number || '') + ' ไม่ใช่ใบร่างแล้ว (' + o.current_status + ') — ดูได้แต่บันทึกทับไม่ได้', 'warning');

			s.savedOrderId = String(o.order_id || id);
			s.savedOrderNumber = String(o.order_number || '');
			s.prio = String(o.priority || '1');
			s.priorMed = String(o.prior_medication || '');
			s.priorSpec = String(o.prior_specify || '');
			if (o.cosign_user_id) s.docId = String(o.cosign_user_id);

			// สิทธิ์ที่ใบบันทึกไว้ — จับคู่กับรายการสิทธิ์ของวิสิท ไม่เจอ = ตกมาชำระเอง
			const savedMain = ((o.inscl_hos || [])[0] || {}).inscl_item_main;
			if (savedMain && savedMain.value) {
				const at = s.insList().findIndex((r) => r.main === String(savedMain.value));
				s.insIx = at >= 0 ? at : -1;
			}

			const missing = [];
			const cart = [];
			(d.lines || []).forEach((l) => {
				const m = masterOf(l.st, l.item_data_id, l.c);
				if (!m) {
					/* หาไม่เจอในแคตตาล็อก (ถูกปิดใช้งาน/ย้ายชนิดหลังออกใบ) — ยังใส่กลับเข้าตะกร้า
					   ด้วยข้อมูลที่อยู่ในใบ · ทิ้งเงียบ = หมอกดบันทึกทับแล้วรายการหายจากใบโดยไม่มีใครรู้ */
					missing.push(l.c || l.n);
					cart.push({ k: l.st + ':' + (l.item_data_id || l.c), st: l.st, id: l.item_data_id, c: l.c, n: l.n,
						p: l.p, cv: 0, sp: '', spn: '', sec: '', qty: l.qty, lab_data: l.lab_data || undefined });
					return;
				}
				cart.push({
					k: l.st + ':' + (m.id || m.c),
					st: l.st,
					id: m.id,
					c: l.c || m.c,
					n: l.n || m.n,
					// 🔴 ราคาใช้ของที่อยู่ในใบ ไม่ใช่ราคา master วันนี้ — ใบเก่าต้องอ่านได้เหมือนวันที่สั่ง
					p: l.p,
					// ส่วนที่ "ใช้แก้ต่อ" เติมจากแคตตาล็อกสด
					cv: m.cv,
					sp: m.sp,
					spn: m.spn,
					sec: m.sec,
					one: m.one === true,
					qty: m.one === true ? 1 : l.qty,
					lab_data: l.lab_data || undefined,
				});
			});
			s.cart = cart;
			// ใบเก่าไม่ได้เก็บธง `set` มาด้วย (และใบก่อน 08-30 ยังมีบรรทัดแม่ของชุด group ปนอยู่)
			// — สร้างใหม่จากแคตตาล็อกด้วยกติกาเดียวกับ server
			normalizeSets();
			s.loadedOrderId = id;
			if (missing.length) {
				field.alert('รายการที่หาไม่เจอในแคตตาล็อกแล้ว ' + missing.length + ' รายการ (' + missing.join(' · ') + ') — ยังอยู่ในใบ แต่แก้ไม่ได้', 'warning');
			}
			// เปิดแท็บให้ตรงกับชนิดของรายการแรก หมอจะได้เห็นของที่ตัวเองสั่งไว้ทันที
			if (cart.length) s.st = cart[0].st;
			s.recompute();
		},
		(err) => {
			s.loadingOrder = false;
			s.orderErr = 'เปิดใบเดิมไม่สำเร็จ: ' + ((err && err.message) || err);
			field.alert(s.orderErr, 'error');
		}
	);
};

/* ══ เริ่มทำงาน — เรียกจาก onMounted ═══════════════════════════════════════ */
s.boot = () => {
	if (!s.ptOk()) return; // ไม่มี visit = ฟอร์มแม่ส่ง context ไม่ครบ · เทมเพลตขึ้นกล่องแดงบอกอยู่แล้ว
	s.loadCatalog();
	s.loadDoctors(); // ต้องมาก่อนกดบันทึก ไม่ใช่โหลดตอนกดช่อง
};

options.onMounted:
// item_screen · onMounted
// ทุกอย่างที่ต้องใช้ getFormRef() (โหลดแคตตาล็อก · โหลดใบเดิม) ต้องรอถึงตรงนี้
// — form instance register ตอน mounted เท่านั้น เรียกใน onCreated จะได้ undefined
this.vueState.boot();

formConfig.cssCode:
/* item-order.css — จอสั่งตรวจ/บริการ (CPOE Order App)
 *
 * แปลงจาก design/mockup/cpoe-item-order.tpl.html (C12) — แก้หน้าตาที่นี่ ไม่ใช่ที่ mockup
 *
 * 🔴 ไฟล์นี้ inject เป็น <style id="sdform-custom-css-<formId>"> ใน <head> = **CSS ระดับ global**
 *    ไม่มีใคร scope ให้ ⇒ ทุก selector ขึ้นต้นด้วย .cpoe-item เอง (<style> ในเทมเพลตใช้ไม่ได้ DOMPurify ตัดทิ้ง)
 * 🔴 mockup เป็นธีมสว่างล้วน (hex ตรงๆ) แต่แอปมีดาร์กโหมด ⇒ token สีทุกตัว map เป็นตัวแปร Element Plus
 *    ยกเว้น --accent เขียวโรงพยาบาล ที่พี่สั่งไว้ว่าห้ามเปลี่ยนกลับ (คงค่าเดิม)
 * 🔴 padding แนวนอนของ .cpoe-item-body ต้องเป็น 0 — pt_header ชิดขอบ container ใส่ padding แล้วจะไม่ตรงกัน
 */

/* ═══ tokens — map เป็นตัวแปร Element Plus เพื่อให้ตามธีม/ดาร์กโหมด ═════════
   ห้ามเขียน hex นอกบล็อกนี้ (กติกาเดิมจาก mockup) */
.cpoe-item {
	--bg: var(--el-bg-color-page);
	--surface: var(--el-bg-color-overlay);
	--surface-warm: var(--el-fill-color-light);
	--fg: var(--el-text-color-primary);
	--fg-2: var(--el-text-color-regular);
	--muted: var(--el-text-color-secondary);
	--border: var(--el-border-color);
	--border-soft: var(--el-border-color-lighter);
	/* 🔴 เขียวโรงพยาบาล — พี่สั่งไว้ว่าห้ามเปลี่ยนกลับเป็นสีระบบ (เดิมม่วง Lingo) */
	--accent: #0d7d5c;
	--accent-on: #ffffff;
	--success: var(--el-color-success);
	--warn: var(--el-color-warning);
	--danger: var(--el-color-danger);
	--info: var(--el-color-primary);
	/* สีเงิน 3 ตัว — ต้องแยกออกจากกันด้วยตาเปล่าเพราะอยู่ติดกันในแถวเดียว
	   🔴 "รวมทั้งใบ" เดิมเป็นสีดำตรงๆ — ใช้ไม่ได้ในดาร์กโหมด ⇒ ตามสีข้อความหลักของธีมแทน
	      (เจตนาเดิมคือ "ยอดกลาง ไม่ใช่สัญญาณเบิก/จ่าย" ซึ่งยังคงอยู่) */
	--money-total: var(--el-text-color-primary);
	--money-claim: var(--el-color-success);
	--money-paid: var(--el-color-danger);
	--font-body: inherit;
	--font-mono: "Roboto Mono", ui-monospace, Menlo, monospace;
	--text-xs: 12px;
	--text-sm: 14px;
	--text-base: 16px;
	--text-lg: 18px;
	--text-xl: 24px;
	--leading-body: 1.55;
	--space-1: 4px;
	--space-2: 8px;
	--space-3: 12px;
	--space-4: 16px;
	--space-5: 20px;
	--space-6: 24px;
	--radius-sm: 10px;
	--radius-md: 10px;
	--radius-lg: 10px;
	--radius-pill: 9999px;
	--elev-ring: 0 0 0 1px var(--border);
	--elev-raised: 0 20px 48px rgba(16, 61, 45, 0.11);
	--focus-ring: 0 0 0 4px color-mix(in oklab, var(--accent), transparent 76%);
	--ease: cubic-bezier(.2,.7,.3,1);
	/* ไอคอนเป็น mask ⇒ สีมาจาก background-color ของตัวที่ใช้ ไม่ต้องมีสีในไฟล์ svg */
	--icon-search: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='%23000'%20stroke-width='2.2'%20stroke-linecap='round'%3E%3Ccircle%20cx='11'%20cy='11'%20r='7'/%3E%3Cpath%20d='M20%2020l-3.8-3.8'/%3E%3C/svg%3E");
	color: var(--fg);
	font-size: var(--text-sm);
	line-height: var(--leading-body);
}

/* ระยะแนวตั้งของจอนี้คุมที่ 2 ค่านี้เท่านั้น — ph margin + body gap
   🔴 อย่าใส่ padding-block ที่ .bar อีกชั้น ระยะจะซ้อนกัน 3 ชั้นแล้วหัวจอลอย (เคยเป็น 40px)
   จอนี้ใช้ 8px แน่นกว่าจอสั่งยา (12px) เพราะมีแถบ segment คั่นอยู่แล้ว ไม่ต้องเว้นซ้ำ */
.cpoe-ph { margin-bottom: 8px; }

/* 🔴 padding แนวนอน 0 เสมอ — ดูหัวไฟล์ */
.cpoe-item-body { display: flex; flex-direction: column; gap: 8px; padding: 0; }

.cpoe-item button { font: inherit; cursor: pointer; }
.cpoe-item input, .cpoe-item select { font: inherit; }
.cpoe-item :focus-visible { outline: none; box-shadow: var(--focus-ring); }
.cpoe-item h3 { margin: 0; line-height: 1.25; letter-spacing: -0.01em; }
.cpoe-item p { margin: 0; }

/* ═══ base ═══════════════════════════════════════════════════════════ */
.cpoe-item *, .cpoe-item *::before, .cpoe-item *::after { box-sizing: border-box; }
.cpoe-item h2{font-size:var(--text-xl);font-weight:800}
.cpoe-item h3{font-size:var(--text-base);font-weight:700}
.cpoe-item .num{font-family:var(--font-mono);font-variant-numeric:tabular-nums}
.cpoe-item .mono{font-family:var(--font-mono)}
.cpoe-item .muted{color:var(--muted)}
.cpoe-item .container{max-width:1680px;margin-inline:auto;padding-inline:28px}

/* ═══ segment service_type ═══════════════════════════════════════════ */
.cpoe-item .bar{display:flex;align-items:center;gap:var(--space-4);padding-block:0}
.cpoe-item .seg{display:inline-flex;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-pill);
  padding:4px;gap:2px;box-shadow:var(--elev-raised)}
.cpoe-item .seg button{border:0;background:none;color:var(--muted);font-weight:700;font-size:var(--text-sm);
  padding:8px 18px;border-radius:var(--radius-pill);display:flex;align-items:center;gap:7px;
  white-space:nowrap}
.cpoe-item .bar{flex-wrap:wrap}
.cpoe-item .seg button:hover{color:var(--fg)}
.cpoe-item .seg button[aria-pressed=true]{background:var(--accent);color:var(--accent-on)}
.cpoe-item .seg .n{font-family:var(--font-mono);font-size:11px;background:color-mix(in oklab,var(--accent),var(--surface) 82%);
  color:color-mix(in oklab,var(--accent),var(--fg) 20%);border-radius:var(--radius-pill);padding:1px 7px;font-weight:700}
.cpoe-item .seg button[aria-pressed=true] .n{background:rgba(255,255,255,.26);color:var(--accent-on)}
.cpoe-item .seg .sepp{width:1px;background:var(--border);margin:5px 6px}

/* สิทธิ์ทั้งใบ + แพทย์ผู้สั่ง — ค่าระดับใบ ต้องอยู่เหนือตะกร้าให้เห็นตลอด */
.cpoe-item .hdset{margin-left:auto;display:flex;align-items:center;gap:var(--space-3);flex-wrap:wrap}
.cpoe-item .fld{display:flex;align-items:center;gap:7px}
.cpoe-item .fld > label{font-size:11px;font-weight:700;color:var(--muted);white-space:nowrap}
.cpoe-item .fld select{border:1px solid var(--border);border-radius:var(--radius-pill);background:var(--surface);
  color:var(--fg-2);font-size:var(--text-xs);font-weight:600;padding:7px 12px;max-width:260px}

/* ความเร่งด่วนทั้งใบ — ทำเป็น chip ไม่ใช่ dropdown เพราะค่า default คือ "ปกติ"
   ถ้าซ่อนใน select คนสั่งด่วนจะมองผ่าน · 5 ค่ากดครั้งเดียวถึงเลย */
.cpoe-item .prio{display:flex;align-items:center;gap:6px}
.cpoe-item .prio button{border:1px solid var(--border);background:var(--surface);color:var(--fg-2);
  border-radius:var(--radius-pill);padding:6px 12px;font-size:11px;font-weight:700;white-space:nowrap}
.cpoe-item .prio button:hover{border-color:var(--accent)}
.cpoe-item .prio button[aria-pressed=true]{background:var(--accent);border-color:var(--accent);color:var(--accent-on)}
/* ระดับด่วนขึ้นไปใช้สีเตือน — ตัวที่เลือกต้องอ่านออกตั้งแต่เหลือบมอง ไม่ใช่แค่ "ติ๊กแล้ว" */
.cpoe-item .prio button.w[aria-pressed=true]{background:var(--warn);border-color:var(--warn);color:var(--accent-on)}
.cpoe-item .prio button.d[aria-pressed=true]{background:var(--danger);border-color:var(--danger);color:var(--accent-on)}

/* "อื่นๆ" = ค่าด่วนเฉพาะบริบท (ด่วนที่สุด/OR/อุบัติเหตุ) — ซ่อนไว้ไม่ให้กินแถบหัวใบทุกวัน */
.cpoe-item .prio .more{position:relative;display:inline-flex}
.cpoe-item .prio .mbtn .cv{font-size:9px;opacity:.7}
.cpoe-item .prio .menu{position:absolute;top:calc(100% + 6px);right:0;z-index:30;display:flex;flex-direction:column;gap:4px;
  background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-sm);
  padding:6px;box-shadow:var(--elev-raised);min-width:150px}
.cpoe-item .prio .menu button{width:100%;text-align:left}

/* เตือนบนหัวใบเมื่อไม่ใช่ "ปกติ" — ใบด่วนต้องเห็นจากทั้งจอ ไม่ใช่เห็นแค่ตรง chip */
.cpoe-item .prio-flag{display:inline-flex;align-items:center;gap:6px;border-radius:var(--radius-pill);
  padding:4px 12px;font-size:11px;font-weight:800;color:var(--accent-on);white-space:nowrap;flex:none}
.cpoe-item .prio-flag.w{background:var(--warn)}
.cpoe-item .prio-flag.d{background:var(--danger)}

/* ยาที่เคยรับ — ถามระดับใบ โผล่เฉพาะใบที่มีรายการ lab */
.cpoe-item .prior{border:1px dashed var(--border);border-radius:var(--radius-sm);padding:var(--space-2) var(--space-3);
  margin-bottom:var(--space-3);background:color-mix(in oklab,var(--surface-warm),var(--surface) 55%)}
.cpoe-item .prior .lb{font-size:11px;font-weight:800;color:var(--muted);letter-spacing:.04em;text-transform:uppercase}
.cpoe-item .prior .why{font-size:11px;color:var(--muted);margin-left:6px}
.cpoe-item .prior .why::before{content:"· ";opacity:.6}
.cpoe-item .prior .opts{display:flex;align-items:center;gap:var(--space-2);flex-wrap:wrap;margin-top:5px}
.cpoe-item .prior .opts button{border:1px solid var(--border);background:var(--surface);color:var(--fg-2);
  border-radius:var(--radius-pill);padding:5px 12px;font-size:var(--text-xs);font-weight:700;white-space:nowrap}
.cpoe-item .prior .opts button[aria-pressed=true]{background:var(--accent);border-color:var(--accent);color:var(--accent-on)}
.cpoe-item .prior input{flex:1 0 100%;min-width:0;margin-top:5px;border:1px solid var(--border);border-radius:var(--radius-pill);
  padding:6px 12px;background:var(--bg);color:var(--fg);font-size:var(--text-xs)}

/* ประวัติการสั่ง */
.cpoe-item .hist{padding:var(--space-4) var(--space-5) var(--space-6);overflow:auto;flex:1;min-height:0}
.cpoe-item .ord{border:1px solid var(--border-soft);border-radius:var(--radius-md);margin-bottom:var(--space-3);overflow:hidden}
.cpoe-item .ord-hd{display:flex;align-items:center;gap:var(--space-3);padding:10px var(--space-4);
  background:color-mix(in oklab,var(--surface-warm),var(--surface) 45%);flex-wrap:wrap}
.cpoe-item .ord-hd .no{font-family:var(--font-mono);font-weight:800;font-size:var(--text-sm)}
.cpoe-item .ord-hd .meta{color:var(--muted);font-size:11px}
.cpoe-item .ord-hd .rt{margin-left:auto;display:flex;align-items:center;gap:var(--space-3)}
.cpoe-item .ord-bd{padding:var(--space-2) var(--space-4) var(--space-3)}
.cpoe-item .ord-row{display:flex;gap:var(--space-3);padding:3px 0;font-size:var(--text-xs);align-items:baseline;
  cursor:pointer;border-radius:var(--radius-sm)}
.cpoe-item .ord-row:hover{background:color-mix(in oklab,var(--surface-warm),var(--surface) 40%)}
.cpoe-item .ord-row input{margin:0;accent-color:var(--accent);width:14px;height:14px;flex:none;
  align-self:center;cursor:pointer}
.cpoe-item .ord-row.off .nm, .cpoe-item .ord-row.off .px{opacity:.45}
.cpoe-item .ord-row.na{cursor:default;opacity:.5}
.cpoe-item .ord-row.na:hover{background:none}
.cpoe-item .ord-row .na-t{font-size:10px;color:var(--muted);flex:none}
.cpoe-item .ord-row .cd{font-family:var(--font-mono);font-size:11px;color:var(--muted);min-width:78px}
.cpoe-item .ord-row .nm{flex:1;min-width:0}
.cpoe-item .ord-row .px{font-family:var(--font-mono);font-size:11px;color:var(--money-total);font-weight:700}
.cpoe-item .st{display:inline-flex;padding:1px 9px;border-radius:var(--radius-pill);font-size:10px;font-weight:800;
  background:var(--surface-warm);color:var(--fg-2)}
.cpoe-item .st.sent, .cpoe-item .st.accepted, .cpoe-item .st.prepared{background:color-mix(in oklab,var(--warn),var(--surface) 78%);
  color:color-mix(in oklab,var(--warn),var(--fg) 34%)}
.cpoe-item .st.ready, .cpoe-item .st.dispensed{background:color-mix(in oklab,var(--money-claim),var(--surface) 84%);
  color:color-mix(in oklab,var(--money-claim),var(--fg) 26%)}
.cpoe-item .st.cancelled, .cpoe-item .st.returned, .cpoe-item .st.reversed{background:color-mix(in oklab,var(--danger),var(--surface) 88%);
  color:color-mix(in oklab,var(--danger),var(--fg) 22%)}

/* ═══ layout ═════════════════════════════════════════════════════════ */
/* สูงเท่าจอ แล้วให้ชีท/ตะกร้า scroll ข้างในกล่องตัวเอง — ปุ่มท้ายตะกร้าจะไม่ถูกดันตกขอบจอ
   ตัวเลข 196px = topbar + แถบผู้ป่วย + แถบ segment */
/* 🔴 ต้องกำหนด height ที่ .work (ไม่ใช่ max-height ที่ลูก) — grid item ยืดตาม content เสมอ
   ปล่อย auto = ติ๊กชีท 230 แถวจะดันคอลัมน์ทะลุกรอบล่างออกไป · คู่กับ min-height:0 ที่ลูกทุกชั้น
   🔴 เลข 330px = หัว popup + การ์ดผู้ป่วย + แถบแพ้ยา + แถบ segment + ระยะขอบ
      (mockup ใช้ 196px เพราะไม่มี chrome ของ popup) · จอไม่พอดี → ปรับเลขนี้ตัวเดียว (ลด = จอสูงขึ้น)
   min-height 640px = พื้นขั้นต่ำตอน popup/จอเตี้ย — ต่ำกว่านี้ติ๊กชีทเหลือไม่กี่แถวจนต้องเลื่อนตลอด
      ค่าเดียวกับจอสั่งยา drug-order.css §.cpoe .main ที่อยู่ใน popup ตัวเดียวกัน */
.cpoe-item .work{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:var(--space-4);
  height:calc(100vh - 330px);min-height:640px}
.cpoe-item .pane{background:var(--surface);border:1px solid var(--border-soft);border-radius:var(--radius-lg);
  box-shadow:var(--elev-raised);overflow:hidden;min-height:0;height:100%}

/* ═══ ติ๊กชีท ════════════════════════════════════════════════════════ */
.cpoe-item .sheet{display:grid;grid-template-columns:236px minmax(0,1fr);height:100%;min-height:0}
.cpoe-item .sheet.norail{grid-template-columns:minmax(0,1fr)}
.cpoe-item .rail{border-right:1px solid var(--border-soft);background:color-mix(in oklab,var(--surface-warm),var(--surface) 45%);
  padding:var(--space-3);display:flex;flex-direction:column;gap:2px;overflow:auto;min-height:0}
.cpoe-item .rail .lb{font-size:11px;font-weight:800;color:var(--muted);letter-spacing:.04em;
  text-transform:uppercase;padding:var(--space-2) var(--space-2) var(--space-1)}
.cpoe-item .rail button{display:flex;align-items:baseline;gap:7px;width:100%;text-align:left;border:0;background:none;
  padding:7px 10px;border-radius:var(--radius-sm);color:var(--fg-2);font-size:var(--text-xs);font-weight:600;line-height:1.35}
.cpoe-item .rail button:hover{background:var(--surface)}
.cpoe-item .rail button[aria-current]{background:var(--accent);color:var(--accent-on)}
.cpoe-item .rail .cd{font-family:var(--font-mono);font-size:11px;font-weight:700;flex:none;min-width:44px}
.cpoe-item .rail .nm{flex:1;min-width:0;overflow-wrap:break-word}
.cpoe-item .rail .tot{font-family:var(--font-mono);font-size:10px;opacity:.62;flex:none}
.cpoe-item .rail .pick{flex:none;background:var(--accent);color:var(--accent-on);border-radius:var(--radius-pill);
  font-family:var(--font-mono);font-size:10px;font-weight:800;padding:0 6px;line-height:16px}
.cpoe-item .rail button[aria-current] .pick{background:var(--accent-on);color:var(--accent)}
/* ระหว่างค้น — section ที่ไม่มีผลลัพธ์จางลง ที่มีผลลัพธ์ติดตัวเลขสีเน้น */
.cpoe-item .rail button.dim{opacity:.4}
.cpoe-item .rail .hit{flex:none;background:color-mix(in oklab,var(--warn),var(--surface) 62%);
  color:color-mix(in oklab,var(--warn),var(--fg) 40%);border-radius:var(--radius-pill);
  font-family:var(--font-mono);font-size:10px;font-weight:800;padding:0 6px;line-height:16px}
.cpoe-item .grp-hd .sec{font-family:var(--font-mono);font-weight:800;opacity:.75}
.cpoe-item .grp-hd .sep{opacity:.45;font-weight:400;margin:0 1px}
.cpoe-item .sh-hd .qx{border:0;background:none;color:var(--muted);font-size:var(--text-base);line-height:1;padding:0 4px}
.cpoe-item .sh-hd .qx:hover{color:var(--danger)}

.cpoe-item .sh{min-width:0;display:flex;flex-direction:column;min-height:0}
.cpoe-item .sh-hd{display:flex;align-items:center;gap:var(--space-3);padding:var(--space-4) var(--space-5);
  border-bottom:1px solid var(--border-soft)}
.cpoe-item .sh-hd h3{flex:none}
/* จอแคบ: ให้บรรทัดสรุปตัดท้ายเอา ไม่ใช่ไปบีบปุ่ม/ช่องค้นหาให้เสียรูป */
.cpoe-item .sh-hd .sub{color:var(--muted);font-size:var(--text-xs);min-width:0;overflow:hidden;
  text-overflow:ellipsis;white-space:nowrap}
.cpoe-item .sh-hd .rt{margin-left:auto;display:flex;align-items:center;gap:var(--space-2);min-width:0;flex:0 1 auto}
.cpoe-item .sh-hd .rt .btn{flex:none}                     /* ปุ่มคงขนาดเสมอ — ตัวที่ยอมหดคือช่องค้นหา */
.cpoe-item .find{position:relative;flex:0 1 auto;min-width:104px}
.cpoe-item .find input{width:230px;max-width:100%;padding:8px 12px 8px 32px;border:1px solid var(--border);border-radius:var(--radius-pill);
  background:var(--bg);color:var(--fg);font-size:var(--text-xs)}
/* ไอคอนแว่นขยาย — ใช้ SVG mask ไม่ใช่ตัวอักษร `⌕`
   glyph ตัวนั้นถูกวาดเล็กกว่า em box ของมันเอง ⇒ ขยาย font-size แล้วยังดูบาง/ไม่สมส่วนกับช่อง
   mask + background-color ทำให้สีตามธีม (var(--muted)) และคุมขนาดเป็น px ได้ตรงๆ */
.cpoe-item .find::before{content:"";position:absolute;left:11px;top:50%;transform:translateY(-50%);
  width:14px;height:14px;background-color:var(--muted);pointer-events:none;
  -webkit-mask:var(--icon-search) center/contain no-repeat;mask:var(--icon-search) center/contain no-repeat}

/* สรุปสิ่งส่งตรวจ — แถบเดียวกับหัวใบกระดาษ ("สิ่งส่งตรวจ") */
.cpoe-item .spec{display:flex;align-items:center;gap:var(--space-2);flex-wrap:wrap;padding:var(--space-3) var(--space-5);
  border-bottom:1px solid var(--border-soft);background:color-mix(in oklab,var(--surface-warm),var(--surface) 55%)}
.cpoe-item .spec .lb{font-size:11px;font-weight:800;color:var(--muted);letter-spacing:.04em;text-transform:uppercase}
.cpoe-item .spec .tube{display:inline-flex;align-items:center;gap:6px;background:var(--surface);border:1px solid var(--border);
  border-radius:var(--radius-pill);padding:3px 11px;font-size:var(--text-xs);font-weight:600}
.cpoe-item .spec .tube .c{font-family:var(--font-mono);font-weight:800;color:var(--accent)}
.cpoe-item .spec .tube .q{font-family:var(--font-mono);font-size:10px;color:var(--muted)}
.cpoe-item .spec .none{color:var(--muted);font-size:var(--text-xs)}

/* แถบกรองกลุ่มเอกซเรย์ — 2 ชั้น: กลุ่ม (สัดส่วนร่างกาย) → ส่วนของร่างกาย
   🔴 ต้องอยู่นอก .sh-bd เหมือน .spec — ถ้าอยู่ข้างในจะเลื่อนหายไปกับเนื้อหา แล้วกรองต่อไม่ได้ */
.cpoe-item .fbar{border-bottom:1px solid var(--border-soft);
  background:color-mix(in oklab,var(--surface-warm),var(--surface) 55%)}
.cpoe-item .fbar .ln{display:flex;align-items:center;gap:var(--space-2);flex-wrap:wrap;padding:var(--space-2) var(--space-5)}
.cpoe-item .fbar .ln+.ln{border-top:1px dashed var(--border-soft)}
.cpoe-item .fbar .lb{font-size:11px;font-weight:800;color:var(--muted);letter-spacing:.04em;
  text-transform:uppercase;flex:none;min-width:74px}
.cpoe-item .fbar .chip{display:inline-flex;align-items:center;gap:6px;background:var(--surface);border:1px solid var(--border);
  border-radius:var(--radius-pill);padding:3px 11px;font-size:var(--text-xs);font-weight:600;color:var(--fg-2)}
.cpoe-item .fbar .chip:hover{border-color:var(--accent);color:var(--accent)}
.cpoe-item .fbar .chip .q{font-family:var(--font-mono);font-size:10px;color:var(--muted)}
.cpoe-item .fbar .chip[aria-pressed="true"]{background:var(--accent);border-color:var(--accent);color:var(--accent-on)}
.cpoe-item .fbar .chip[aria-pressed="true"] .q{color:var(--accent-on);opacity:.75}
/* ติ๊กแล้วกี่ตัวในกลุ่มนั้น — ให้เห็นว่าเคยแวะกลุ่มไหนไปแล้วโดยไม่ต้องกดเข้าไปดู */
.cpoe-item .fbar .chip .pk{font-family:var(--font-mono);font-size:10px;font-weight:800;background:var(--accent);
  color:var(--accent-on);border-radius:var(--radius-pill);padding:0 6px;line-height:15px}
.cpoe-item .fbar .chip[aria-pressed="true"] .pk{background:var(--accent-on);color:var(--accent)}
/* กลุ่มที่ยังไม่ได้จัด — สีกลางๆ ไม่ให้เด่นกว่ากลุ่มจริง แต่ยังกดได้ */
.cpoe-item .fbar .chip.rest{border-style:dashed;color:var(--muted)}

/* 🔴 กล่อง scroll กับกล่อง column ต้องแยกกัน — ถ้ากล่องเดียวกันมีทั้ง overflow:auto และ
   column-width เนื้อหาจะไหลเป็นคอลัมน์ออกทางขวาไม่รู้จบ (scrollWidth ทะลุ 4,000px)
   แทนที่จะ scroll ลง · .sh-bd ทำหน้าที่ scroll · .cols ข้างในสูงตามเนื้อหาแล้วแบ่งคอลัมน์เอง */
.cpoe-item .sh-bd{padding:var(--space-4) var(--space-5) var(--space-6);overflow:auto;flex:1;min-height:0}
.cpoe-item .cols{column-width:268px;column-gap:var(--space-5)}
.cpoe-item .grp{break-inside:avoid;margin-bottom:var(--space-4);border:1px solid var(--border-soft);
  border-radius:var(--radius-sm);overflow:hidden}
/* กลุ่มยาวกว่าคอลัมน์ต้องยอมให้ไหลข้ามคอลัมน์ ไม่งั้นบล็อกเดียวกินทั้งชีท (เช่น MI-OUT 230 รายการ) */
.cpoe-item .grp.big{break-inside:auto;overflow:visible}
.cpoe-item .grp-hd{background:var(--surface-warm);padding:5px var(--space-3);font-size:var(--text-xs);font-weight:800;
  color:color-mix(in oklab,var(--accent),var(--fg) 24%);display:flex;align-items:center;gap:var(--space-2)}
.cpoe-item .grp-hd .n{margin-left:auto;font-family:var(--font-mono);font-size:10px;font-weight:700;opacity:.6}
.cpoe-item .grp-all{border:1px solid color-mix(in oklab,var(--accent),var(--surface) 62%);background:var(--surface);
  color:var(--accent);font-size:10px;font-weight:800;border-radius:var(--radius-pill);
  padding:0 8px;line-height:16px;flex:none}
.cpoe-item .grp-all:hover{background:var(--accent);color:var(--accent-on);border-color:var(--accent)}
.cpoe-item .grp-all.on{background:var(--accent);color:var(--accent-on);border-color:var(--accent)}
.cpoe-item .grp-bd{padding:3px 0}
.cpoe-item .row{display:flex;align-items:flex-start;gap:7px;padding:3px var(--space-3);cursor:pointer;line-height:1.4}
.cpoe-item .row:hover{background:color-mix(in oklab,var(--surface-warm),var(--surface) 35%)}
.cpoe-item .row input{margin:2px 0 0;accent-color:var(--accent);width:14px;height:14px;flex:none;cursor:pointer}
.cpoe-item .row .cd{font-family:var(--font-mono);font-size:11px;font-weight:700;color:var(--muted);flex:none;min-width:38px}
.cpoe-item .row .nm{flex:1;min-width:0;font-size:var(--text-xs)}
.cpoe-item .row .px{font-family:var(--font-mono);font-size:10px;color:var(--muted);flex:none}
.cpoe-item .row.on{background:color-mix(in oklab,var(--accent),var(--surface) 92%)}
.cpoe-item .row.on .nm{font-weight:700}
.cpoe-item .row.on .cd{color:var(--accent)}
.cpoe-item .row mark{background:color-mix(in oklab,var(--warn),var(--surface) 62%);color:inherit;border-radius:3px}

/* ── ชุดแม่-ลูก (C33) — แถวในติ๊กชีท ───────────────────────────────────────
   ลูก **ติ๊กเองได้แล้ว** (ต่างจาก C31 เดิม) ⇒ ยังเป็นแถวกดได้ปกติ แค่เยื้องให้เห็นว่าอยู่ในชุด
   ไม่ใช้สีจางทั้งแถว เพราะชื่อเทสต์ยังต้องอ่านออกตอนค้นหา */
.cpoe-item .row.kid{padding-left:calc(var(--space-3) + 10px)}
.cpoe-item .row .kid-mark{flex:none;width:14px;color:var(--muted);font-size:11px;line-height:1.4}
.cpoe-item .row.kid .nm{color:var(--el-text-color-regular)}

/* ── การ์ดชุด (sub_order) — ทั้งการ์ดคือ 1 ตัวเลือก ──────────────────────
   พี่สั่ง 2026-08-30: แยกออกจากการ์ด lab_group ไปเลย เพราะทั้งชุดสั่งพร้อมกันเสมอ
   🔴 ในการ์ดนี้ห้ามมี checkbox ที่ไหนเลย — ตาต้องอ่านออกทันทีว่า "เลือกได้ทั้งใบเท่านั้น" */
.cpoe-item .grp.setcard{border-color:color-mix(in oklab,var(--accent),var(--border) 55%)}
.cpoe-item .grp.setcard.on{border-color:var(--accent)}
.cpoe-item .grp-hd.set-hd{display:flex;align-items:center;gap:var(--space-2);cursor:pointer;
  background:color-mix(in oklab,var(--accent),var(--surface) 90%)}
.cpoe-item .grp-hd.set-hd:hover{background:color-mix(in oklab,var(--accent),var(--surface) 84%)}
.cpoe-item .grp.setcard.on .grp-hd.set-hd{background:color-mix(in oklab,var(--accent),var(--surface) 78%)}
/* (.set-badge / .set-px ถอดออก 2026-08-30 — พี่สั่ง: หัวการ์ดไม่ต้องมีป้าย "ชุด" และไม่ต้องมีราคา) */
.cpoe-item .set-hd .set-cd{flex:none;font-family:var(--font-mono);font-size:var(--text-xs);
  font-weight:700;color:var(--accent)}
.cpoe-item .set-hd .set-nm{flex:1 1 auto;min-width:0;font-weight:700;overflow-wrap:break-word}
.cpoe-item .set-hd .set-btn{flex:none;white-space:nowrap}
/* แถวลูกในการ์ดชุด — โชว์ว่าจะได้อะไรบ้าง กดไม่ได้ (เลือกที่หัวการ์ด) ⇒ cursor ปกติ ไม่มี hover */
.cpoe-item .row.inset{cursor:default;padding-left:calc(var(--space-3) + 10px)}
.cpoe-item .row.inset:hover{background:none}
.cpoe-item .row.inset .nm{color:var(--el-text-color-regular)}
/* (.set-hint ถูกถอดออก 2026-08-30 — พี่สั่ง: ไม่ต้องมีข้อความ "หรือสั่งเป็นชุด" บนแถวลูก) */
/* ป้ายบอกว่ากดทีเดียวได้ทั้งชุด — ไม่งั้นหมอไม่รู้ว่าทำไมกด 1 แล้วขึ้นในตะกร้าหลายบรรทัด */
.cpoe-item .row .set-tag{display:inline-block;margin-left:6px;padding:0 5px;border-radius:999px;
  background:color-mix(in oklab,var(--accent),var(--surface) 86%);color:var(--accent);
  font-size:10px;font-weight:700;white-space:nowrap;vertical-align:1px}


/* ═══ แบบสั่งยา (picker) ═════════════════════════════════════════════ */
.cpoe-item .pick-wrap{display:flex;flex-direction:column;height:100%;min-height:0}
.cpoe-item .pick-hd{padding:var(--space-4) var(--space-5);border-bottom:1px solid var(--border-soft);
  display:flex;align-items:center;gap:var(--space-3)}
.cpoe-item .pick-hd .find input{width:340px}
.cpoe-item .plist{overflow:auto;flex:1;min-height:0;padding:var(--space-2) var(--space-3) var(--space-5)}
.cpoe-item .prow{display:flex;align-items:center;gap:var(--space-4);padding:6px var(--space-4);
  border-radius:var(--radius-sm);cursor:pointer;border:1px solid transparent;margin-bottom:3px}
.cpoe-item .prow:hover{background:var(--surface-warm);border-color:var(--border)}
/* รหัสชิดขวาเข้าหาชื่อ — คอลัมน์ตัวเลขอ่านง่ายกว่าเมื่อจบท้ายตรงกัน และไม่ทิ้งช่องว่างกลาง */
.cpoe-item .prow .cd{font-family:var(--font-mono);font-size:11px;font-weight:700;color:var(--muted);
  flex:none;min-width:72px;text-align:right}
.cpoe-item .prow .nm{flex:1;min-width:0;padding-left:var(--space-2)}
.cpoe-item .prow .nm b{display:block;font-weight:700;line-height:1.3}
.cpoe-item .prow .nm small{display:block;color:var(--muted);font-size:10px;line-height:1.25}
.cpoe-item .prow .px{font-family:var(--font-mono);font-size:var(--text-xs);font-weight:700;flex:none;
  min-width:74px;text-align:right;color:var(--money-total)}
.cpoe-item .prow .add{flex:none;border:1px solid var(--border);background:var(--surface);border-radius:var(--radius-pill);
  color:var(--accent);font-weight:800;font-size:11px;padding:3px 12px;margin-left:var(--space-2)}
.cpoe-item .prow.on{background:color-mix(in oklab,var(--accent),var(--surface) 93%);border-color:var(--border)}
.cpoe-item .empty{color:var(--muted);text-align:center;padding:var(--space-6);font-size:var(--text-xs)}

/* ═══ ประวัติการสั่ง ═════════════════════════════════════════════════ */
/* ═══ ตะกร้า ═════════════════════════════════════════════════════════ */
.cpoe-item .cart{display:flex;flex-direction:column;min-height:0}
.cpoe-item .cart-hd{display:flex;align-items:center;gap:var(--space-2);padding:var(--space-4) var(--space-4) var(--space-3);
  border-bottom:1px solid var(--border-soft)}
.cpoe-item .cart-hd .n{font-family:var(--font-mono);font-size:var(--text-xs);color:var(--muted)}
.cpoe-item .cart-hd .rt{margin-left:auto}
.cpoe-item .lines{overflow:auto;padding:var(--space-2);flex:1;min-height:0}
.cpoe-item .line{border:1px solid var(--border-soft);border-left:3px solid var(--border);
  border-radius:var(--radius-sm);padding:9px var(--space-3);
  margin-bottom:6px;display:flex;gap:var(--space-2);align-items:flex-start}
.cpoe-item .line.lab{border-left-color:var(--accent)}
.cpoe-item .line.xray{border-left-color:var(--warn)}
.cpoe-item .line.nurs{border-left-color:var(--info)}
.cpoe-item .line.order{border-left-color:var(--muted)}
.cpoe-item .line .bd{flex:1;min-width:0}
.cpoe-item .line .t{display:flex;align-items:flex-start;gap:6px;min-width:0}
.cpoe-item .line .t b{font-size:var(--text-xs);font-weight:700;line-height:1.35;flex:1;min-width:0;
  overflow-wrap:anywhere}
.cpoe-item .line .t .tag{flex:none;margin-top:1px}
.cpoe-item .line .m .cd{font-family:var(--font-mono);font-size:10px;color:var(--muted);flex:none}
.cpoe-item .line .m{color:var(--muted);font-size:11px;margin-top:2px;display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.cpoe-item .line .px{font-family:var(--font-mono);font-size:var(--text-xs);font-weight:700;flex:none;text-align:right}
.cpoe-item .line .rm{flex:none;border:0;background:none;color:var(--muted);font-size:var(--text-base);line-height:1;padding:0 2px}
.cpoe-item .line .rm:hover{color:var(--danger)}

/* ── ชุดแม่-ลูก (C31) — บรรทัดลูกในตะกร้า ──────────────────────────────────
   เยื้องเข้า + ขอบซ้ายจาง = อ่านออกทันทีว่าเป็นของที่ห้อยกับบรรทัดบน
   ไม่มีปุ่มจำนวน/ปุ่มลบ (จัดการที่แม่) ⇒ ใส่ตัวยึดที่กว้างเท่าปุ่มลบ ไม่งั้นคอลัมน์ราคาเหลื่อม */
.cpoe-item .line.kid{margin-left:14px;border-left-color:var(--border-soft);
  background:color-mix(in oklab,var(--surface-warm),var(--surface) 55%)}
.cpoe-item .line.kid .t b{font-weight:600}
.cpoe-item .line .kid-mark{flex:none;color:var(--muted);font-size:11px;line-height:1.5;margin-top:1px}
/* (.rm-off ถูกถอดออกพร้อมกติกาเก่า — ทุกบรรทัดมีปุ่มลบจริงแล้ว ไม่ต้องมีตัวยึดคอลัมน์) */
.cpoe-item .tag{display:inline-flex;padding:0 7px;border-radius:var(--radius-pill);font-size:10px;font-weight:800;
  background:var(--surface-warm);color:color-mix(in oklab,var(--accent),var(--fg) 24%)}
/* 1 สีต่อ 1 ชนิดรายการ — ใบเดียวมีหลายชนิดปนได้ ต้องแยกออกจากกันด้วยตาเปล่า */
.cpoe-item .tag.lab{background:color-mix(in oklab,var(--accent),var(--surface) 84%);
  color:color-mix(in oklab,var(--accent),var(--fg) 22%)}
.cpoe-item .tag.xray{background:color-mix(in oklab,var(--warn),var(--surface) 78%);
  color:color-mix(in oklab,var(--warn),var(--fg) 34%)}
.cpoe-item .tag.nurs{background:color-mix(in oklab,var(--info),var(--surface) 86%);
  color:color-mix(in oklab,var(--info),var(--fg) 26%)}
.cpoe-item .tag.order{background:var(--surface-warm);color:var(--fg-2)}
.cpoe-item .qty{display:inline-flex;align-items:center;border:1px solid var(--border);border-radius:var(--radius-pill);
  overflow:hidden;background:var(--surface)}
.cpoe-item .qty button{border:0;background:none;color:var(--accent);font-weight:800;padding:0 8px;line-height:20px}
.cpoe-item .qty span{font-family:var(--font-mono);font-size:11px;font-weight:700;min-width:20px;text-align:center}

/* เตือนเมื่อรายการนั้นยังไม่รู้ว่าเก็บสิ่งส่งตรวจอะไร — ห้องแลปรับใบไปแล้วเจอทีหลังจะเสียเวลาตามคนไข้ */
/* บรรทัดเดียวเสมอ — ข้อมูลเต็มอยู่ใน tooltip · แถบนี้แทรกอยู่ในทุกบรรทัด lab
   ถ้ายอมให้ตัดบรรทัด ตะกร้า 20 รายการจะยาวขึ้นเท่าตัว
   ดีไซน์: ไม่มีกรอบรอบ ใช้แถบสีซ้าย + พื้นอ่อน ให้อ่านเป็นส่วนขยายของการ์ด ไม่ใช่ alert แปะทับ */
.cpoe-item .needspec{margin-top:4px;display:flex;align-items:center;gap:6px;min-width:0;
  background:color-mix(in oklab,var(--warn),var(--surface) 88%);
  border-left:2px solid var(--warn);
  border-radius:0 var(--radius-sm) var(--radius-sm) 0;
  padding:3px 4px 3px 8px;font-size:10px;line-height:1.45;
  color:color-mix(in oklab,var(--warn),var(--fg) 40%);font-weight:600}
.cpoe-item .needspec .txt{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* ไอคอนวาดเอง — emoji สีสดไม่เข้ากับจานสีและขนาดเพี้ยนข้ามเครื่อง */
.cpoe-item .needspec .ic{flex:none;width:13px;height:13px;border-radius:50%;display:grid;place-items:center;
  background:var(--warn);color:var(--surface);font-size:9px;font-weight:900;line-height:1}
.cpoe-item .needspec.done{background:color-mix(in oklab,var(--money-claim),var(--surface) 92%);
  border-left-color:var(--money-claim);
  color:color-mix(in oklab,var(--money-claim),var(--fg) 32%)}
.cpoe-item .needspec.done .ic{background:var(--money-claim)}
.cpoe-item .needspec.done{background:color-mix(in oklab,var(--money-claim),var(--surface) 88%);
  border-color:color-mix(in oklab,var(--money-claim),var(--surface) 62%);
  color:color-mix(in oklab,var(--money-claim),var(--fg) 28%)}
.cpoe-item .needspec .fill{flex:none;border:0;background:var(--warn);color:#fff;
  font-weight:800;font-size:10px;border-radius:var(--radius-pill);padding:0 9px;line-height:16px;
  letter-spacing:.01em}
.cpoe-item .needspec .fill:hover{background:color-mix(in oklab,var(--warn),black 12%)}
.cpoe-item .needspec.done .fill{background:transparent;color:inherit;border:1px solid currentColor;opacity:.75}
.cpoe-item .needspec.done .fill:hover{background:var(--surface);opacity:1}

.cpoe-item .ask{position:fixed;inset:0;z-index:60;background:color-mix(in oklab,var(--fg),transparent 45%);
  display:none;place-items:center;padding:20px}
.cpoe-item .ask.open{display:grid}
.cpoe-item .ask-box{background:var(--surface);border-radius:var(--radius-lg);box-shadow:var(--elev-raised);
  width:min(560px,100%);padding:var(--space-5);max-height:90vh;overflow:auto}
.cpoe-item .ask-box h3{margin-bottom:4px}
.cpoe-item .ask-box .for{color:var(--muted);font-size:12px;margin-bottom:var(--space-4)}
.cpoe-item .ask-box .for b{color:var(--fg-2)}
.cpoe-item .fgrid{display:grid;gap:var(--space-3);margin-bottom:var(--space-4)}
.cpoe-item .fgrid label{display:block;font-size:11px;font-weight:700;color:var(--muted);margin-bottom:3px}
.cpoe-item .fgrid input[type=text], .cpoe-item .fgrid input[type=datetime-local], .cpoe-item .fgrid select{width:100%;border:1px solid var(--border);
  border-radius:var(--radius-sm);background:var(--bg);color:var(--fg);padding:8px 11px;font-size:var(--text-xs)}
.cpoe-item .radios{display:flex;gap:var(--space-4);flex-wrap:wrap}
.cpoe-item .radios label{display:inline-flex;align-items:center;gap:6px;font-size:var(--text-xs);
  font-weight:600;color:var(--fg-2);margin:0;text-transform:none;cursor:pointer}
.cpoe-item .radios input{accent-color:var(--accent);width:15px;height:15px;margin:0}
.cpoe-item .ask-acts{display:flex;gap:var(--space-2);justify-content:flex-end}

/* บล็อกการส่งใบ — บอกเหตุผลตรงจุดที่กด ไม่ใช่รอให้กดแล้วเด้ง alert */
.cpoe-item .block{display:flex;align-items:center;gap:7px;margin-bottom:var(--space-3);
  background:color-mix(in oklab,var(--danger),var(--surface) 94%);
  border-left:2px solid var(--danger);
  border-radius:0 var(--radius-sm) var(--radius-sm) 0;
  padding:7px 6px 7px 10px;font-size:11px;font-weight:600;
  color:color-mix(in oklab,var(--danger),var(--fg) 26%)}
.cpoe-item .block .ic{flex:none;width:15px;height:15px;border-radius:50%;display:grid;place-items:center;
  background:var(--danger);color:#fff;font-size:10px;font-weight:900;line-height:1}
.cpoe-item .block .go{margin-left:auto;flex:none;border:0;background:var(--danger);color:#fff;
  font-weight:800;font-size:10px;border-radius:var(--radius-pill);padding:2px 10px}
.cpoe-item .block .go:hover{background:color-mix(in oklab,var(--danger),black 12%)}
@keyframes cpoe-item-cpoe-item-flash{0%,100%{box-shadow:none}30%{box-shadow:0 0 0 3px color-mix(in oklab,var(--danger),transparent 55%)}}
.cpoe-item .line.flash {animation:cpoe-item-flash 1.1s ease}

.cpoe-item .cart-ft {border-top:1px solid var(--border-soft);padding:var(--space-3) var(--space-4);background:var(--surface)}
/* ยอดเงิน 3 ช่อง — ขนาดและเส้นฐานต้องตรงกันทั้งแถว ไม่งั้นตาอ่านว่าช่องหนึ่งสำคัญกว่า
   ทั้งที่เป็นข้อมูลระดับเดียวกัน · แยกความหมายด้วยสีอย่างเดียวพอ */
.cpoe-item .totals {display:flex;gap:var(--space-5);margin-bottom:var(--space-3);flex-wrap:wrap}
.cpoe-item .totals span {display:flex;flex-direction:column;gap:1px;color:var(--muted);font-size:11px;line-height:1.35}
.cpoe-item .totals b {font-family:var(--font-mono);font-size:var(--text-base);font-weight:800;line-height:1.2}
.cpoe-item .totals .m-total b {color:var(--money-total)}
.cpoe-item .totals .m-claim b {color:var(--money-claim)}
.cpoe-item .totals .m-paid  b {color:var(--money-paid)}
.cpoe-item .line .px {color:var(--money-total)}
.cpoe-item .m-claim-t {color:var(--money-claim);font-weight:700}
.cpoe-item .m-paid-t {color:var(--money-paid);font-weight:700}
.cpoe-item .acts {display:flex;gap:var(--space-2)}
.cpoe-item .btn {border:1px solid var(--border);background:var(--surface);color:var(--fg-2);font-weight:700;
  padding:9px 16px;border-radius:var(--radius-pill);font-size:var(--text-xs);
  white-space:nowrap}   /* 🔴 ปุ่ม pill ที่ตัดคำได้ = ข้อความ 2-3 บรรทัดในวงกลม (เจอตอนจอ ~1000px) */
.cpoe-item .btn:hover {background:var(--surface-warm)}
.cpoe-item .btn:disabled {opacity:.45;cursor:not-allowed}
.cpoe-item .btn-primary {background:var(--accent);border-color:var(--accent);color:var(--accent-on);flex:1}
.cpoe-item .btn-primary:hover {background:color-mix(in oklab,var(--accent),black 8%)}

/* ═══ note ═══════════════════════════════════════════════════════════ */
.cpoe-item .note {margin:var(--space-4) 0 56px;border:1px dashed var(--border);border-radius:var(--radius-md);
  padding:var(--space-4) var(--space-5);color:var(--muted);font-size:var(--text-xs);line-height:1.7}
.cpoe-item .note h3 {font-size:var(--text-xs);color:var(--fg-2);margin-bottom:var(--space-2);letter-spacing:.04em;
  text-transform:uppercase}
.cpoe-item .note .live {border-bottom:1px dashed var(--border);padding-bottom:var(--space-3);margin-bottom:var(--space-3);
  display:grid;gap:4px}
.cpoe-item .note .live p {color:var(--fg-2)}
.cpoe-item .note b {color:var(--fg-2)}
.cpoe-item .note code {font-family:var(--font-mono);font-size:11px;background:var(--surface-warm);
  padding:1px 5px;border-radius:5px;color:color-mix(in oklab,var(--accent),var(--fg) 24%)}
.cpoe-item .note ul {margin:0;padding-left:18px}
.cpoe-item .note li {margin-bottom:3px}

@media (max-width:1200px){
  /* จอแคบ — เลิกบังคับความสูงเท่าจอ ปล่อยให้หน้า scroll ตามปกติ */
  .cpoe-item .work {grid-template-columns:minmax(0,1fr);height:auto}
  .cpoe-item .pane {height:auto}
  .cpoe-item .sheet {grid-template-columns:204px minmax(0,1fr);height:auto}
  .cpoe-item .rail, .cpoe-item .sh-bd, .cpoe-item .plist, .cpoe-item .lines {max-height:62vh}
}

/* LAB launcher: เลือก VN ก่อนสร้าง CPOE Order */
.cpoe-vn-picker{margin-bottom:8px;padding:10px 12px;border:1px solid var(--el-border-color-lighter);border-radius:10px;background:var(--el-fill-color-light)}
.cpoe-vn-search{display:flex;gap:8px;align-items:center}.cpoe-vn-search .el-input{width:min(360px,100%)}
.cpoe-vn-error{margin-top:6px;color:var(--el-color-danger);font-size:12px}
.cpoe-vn-row{display:grid;grid-template-columns:130px minmax(0,1fr) auto;gap:10px;align-items:center;width:100%;margin-top:6px;padding:8px 10px;border:0;border-bottom:1px dashed var(--el-border-color-lighter);background:transparent;text-align:left;color:var(--el-text-color-regular)}
.cpoe-vn-row:hover,.cpoe-vn-row.is-selected{background:var(--el-bg-color);color:var(--el-color-primary)}
.cpoe-vn-code{font-family:var(--font-mono);font-weight:700}.cpoe-vn-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cpoe-vn-age{color:var(--el-text-color-secondary);font-size:12px}
@media(max-width:720px){.cpoe-vn-search{align-items:stretch;flex-direction:column}.cpoe-vn-search .el-input{width:100%}.cpoe-vn-row{grid-template-columns:1fr}.cpoe-vn-name{white-space:normal}}
